INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-1-u3-C32','kor',3,1,'u3',11,'받침 ㄱ · ㅂ 뒤 ㅎ 소리 — 받침 ㄱ · ㅂ 뒤에 ㅎ이 오면 [ㅋ] · [ㅍ]으로 소리 남(축하 [추카] · 급히 [그피])',ARRAY['단원 통합 기초 다지기(케이티처 표기 · 발음 · 표준어 — 번호 W7)']::text[],32) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
