INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-1-u3-X01','kor',3,'u3',ARRAY['K3-1-u3-C1','K3-1-u3-C2']::text[],'글은 생각나는 대로 늘어놓으면 된다고 여겨 짜임새를 생각하지 않는다','읽는 사람을 생각해요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-1-u3-X02','kor',3,'u3',ARRAY['K3-1-u3-C3']::text[],'문장 하나하나를 따로 한 문단이라고 여겨 문장마다 줄을 바꾼다','문단은 문장이 모인 것') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-1-u3-X03','kor',3,'u3',ARRAY['K3-1-u3-C3','K3-1-u3-C6']::text[],'한 문단에 여러 가지 생각을 섞어 쓴다','한 문단에 한 생각') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-1-u3-X04','kor',3,'u3',ARRAY['K3-1-u3-C4','K3-1-u3-C7']::text[],'가장 긴 문장이 중심 문장이라고 여긴다','길이가 아니라 대표') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-1-u3-X05','kor',3,'u3',ARRAY['K3-1-u3-C8']::text[],'중심 문장은 언제나 문단 맨 앞에만 온다고 여긴다','끝에도 올 수 있어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-1-u3-X06','kor',3,'u3',ARRAY['K3-1-u3-C4','K3-1-u3-C5']::text[],'중심 문장과 뒷받침 문장을 바꾸어 안다(예를 든 문장을 중심 문장으로 고른다)','어느 문장이 다른 문장을 묶나요?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-1-u3-X07','kor',3,'u3',ARRAY['K3-1-u3-C6']::text[],'문단을 시작할 때 들여 쓰지 않거나 새 문단에서 줄을 바꾸지 않는다','한 칸 들여, 새 문단은 줄 바꿈') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-1-u3-X08','kor',3,'u3',ARRAY['K3-1-u3-C5']::text[],'뒷받침 문장은 중심 문장을 낱말만 바꾸어 되풀이하는 문장이라고 여긴다','자세히 · 예를 들어') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-1-u3-X09','kor',3,'u3',ARRAY['K3-1-u3-C9','K3-1-u3-C10']::text[],'중심 문장과 관계없는 문장도 뒷받침 문장이 될 수 있다고 여긴다','같은 생각을 말하나요?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-1-u3-X10','kor',3,'u3',ARRAY['K3-1-u3-C10']::text[],'어울리지 않는 문장을 찾고도 또 다른 관계없는 문장으로 바꾼다','중심 생각에 맞게 바꿔요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-1-u3-X11','kor',3,'u3',ARRAY['K3-1-u3-C12']::text[],'중심 문장 하나만 쓰면 문단이 된다고 여긴다','뒷받침 문장이 있어야 해요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-1-u3-X12','kor',3,'u3',ARRAY['K3-1-u3-C11']::text[],'쓸 내용을 정하지 않고 쓰다가 중심 생각이 바뀐다','먼저 계획해요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-1-u3-X13','kor',3,'u3',ARRAY['K3-1-u3-C13']::text[],'다 쓴 글을 점검하지 않거나 글자 수 · 길이만 살핀다','중심 · 뒷받침 · 들여쓰기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-1-u3-X14','kor',3,'u3',ARRAY['K3-1-u3-C14','K3-1-u3-C15']::text[],'재미와 감동을 같은 것으로 여기거나 웃겨야만 좋은 작품이라고 여긴다','웃음도, 뭉클함도') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-1-u3-X15','kor',3,'u3',ARRAY['K3-1-u3-C16']::text[],'떠오르는 장면은 생각하지 않고 글자만 읽는다','눈앞에 그려 봐요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-1-u3-X16','kor',3,'u3',ARRAY['K3-1-u3-C17']::text[],'작품과 관계없는 내 이야기를 늘어놓는 것을 비슷한 경험이라고 여긴다','작품과 닮은 일') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-1-u3-X17','kor',3,'u3',ARRAY['K3-1-u3-C18']::text[],'낭송은 빨리, 크게만 읽으면 된다고 여긴다','마음을 살려') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-1-u3-X18','kor',3,'u3',ARRAY['K3-1-u3-C19']::text[],'「좋았어요.」처럼 느낀 점만 말하고 까닭은 말하지 않는다','왜 그렇게 느꼈나요?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-1-u3-X19','kor',3,'u3',ARRAY['K3-1-u3-C20']::text[],'감상에는 정답이 하나라 친구와 다르게 느끼면 잘못 느낀 것이라고 여긴다','느낌은 저마다') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-1-u3-X20','kor',3,'u3',ARRAY['K3-1-u3-C21']::text[],'인물이나 일어난 일, 인물의 마음을 바꾸어 안다','누가 무엇을 했나요?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-1-u3-X21','kor',3,'u3',ARRAY['K3-1-u3-C22']::text[],'사건의 차례를 뒤섞는다','처음 · 가운데 · 끝') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-1-u3-X22','kor',3,'u3',ARRAY['K3-1-u3-C23']::text[],'모르는 낱말의 뜻을 앞뒤 문장을 보지 않고 낱말 소리만으로 짐작하거나 건너뛴다','앞뒤 문장을 봐요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-1-u3-X23','kor',3,'u3',ARRAY['K3-1-u3-C24']::text[],'감상 문단에서 까닭을 빼거나 느낀 부분과 까닭을 바꾸어 쓴다','느낀 부분 = 중심, 까닭 = 뒷받침') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-1-u3-X24','kor',3,'u3',ARRAY['K3-1-u3-C25']::text[],'재미와 감동은 글로만(또는 한 가지 방법으로만) 표현할 수 있다고 여긴다','몸 · 그림 · 글') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-1-u3-X25','kor',3,'u3',ARRAY['K3-1-u3-C26']::text[],'표현 방법의 특징을 바꾸어 안다(편지를 몸짓으로, 역할극을 그림으로)','몸일까, 그림일까, 글일까?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-1-u3-X26','kor',3,'u3',ARRAY['K3-1-u3-C27']::text[],'친구의 작품이나 느낌을 그대로 따라 하는 것도 나의 표현이라고 여긴다','내 느낌으로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-1-u3-X27','kor',3,'u3',ARRAY['K3-1-u3-C28']::text[],'「나」 설명서에 나와 관계없는 이야기나 친구의 비밀을 넣는다','나를 보여 주는 내용만') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-1-u3-X28','kor',3,'u3',ARRAY['K3-1-u3-C29']::text[],'소개 자료에 작품 제목이나 느낀 까닭을 빠뜨린다','제목 · 느낌 · 까닭') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-1-u3-X29','kor',3,'u3',ARRAY['K3-1-u3-C31','K3-1-u3-C32']::text[],'받침을 글자 그대로 읽는다(입학 → [입학])','소리가 바뀌어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-1-u3-X30','kor',3,'u3',ARRAY['K3-1-u3-C31','K3-1-u3-C32']::text[],'ㅎ이 만나 바뀌는 소리를 다른 소리로 읽는다(놓고 → [노고] · 축하 → [추가])','ㅎ이 만나면 [ㅋ] · [ㅌ] · [ㅊ] · [ㅍ]') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-1-u3-X31','kor',3,'u3',ARRAY['K3-1-u3-C33']::text[],'뜻이 같은 두 말 가운데 하나만 표준어라고 여긴다','둘 다 표준어') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-1-u3-X32','kor',3,'u3',ARRAY['K3-1-u3-C30']::text[],'짜임새 있게 쓰기는 국어 시간에만 쓰는 것이라고 여긴다','생활 속에서도') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
