INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u3_L02_basic#4','kor',3,1,'u3','L02','g3_1_kor_u3_L02_basic','lesson_basic','K3-1-u3-C1',1,'mc','auto','이 단원에서 배울 두 가지로 알맞은 것은 무엇일까요?',ARRAY['K3-1-u3-X01','K3-1-u3-X02','K3-1-u3-X26']::text[],false,'{"seq":4,"concept":"K3-1-u3-C1","difficulty":1,"kind":"mc","stem":"이 단원에서 배울 두 가지로 알맞은 것은 무엇일까요?","options":[{"t":"짜임새 있게 문단 쓰기 · 작품의 재미와 감동 표현하기","correct":true},{"t":"생각나는 대로 길게 쓰기 · 작품을 빨리 읽기","mis":"K3-1-u3-X01"},{"t":"문장마다 줄 바꾸어 쓰기 · 웃긴 부분만 찾기","mis":"K3-1-u3-X02"},{"t":"친구 글 베껴 쓰기 · 친구와 똑같이 느끼기","mis":"K3-1-u3-X26"}],"explanation":["문단","재미와 감동","두 가지"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u3_L02_basic#5','kor',3,1,'u3','L02','g3_1_kor_u3_L02_basic','lesson_basic','K3-1-u3-C4',2,'mc','auto','「고양이의 수염」의 중심 문장은 무엇일까요?',ARRAY['K3-1-u3-X04','K3-1-u3-X06']::text[],false,'{"seq":5,"concept":"K3-1-u3-C4","difficulty":2,"kind":"mc","stem":"「고양이의 수염」의 중심 문장은 무엇일까요?","options":[{"t":"고양이의 수염은 쓸모가 많습니다.","correct":true},{"t":"고양이는 수염으로 좁은 틈을 지나갈 수 있는지 잽니다.","mis":"K3-1-u3-X04"},{"t":"어두운 곳에서는 수염으로 둘레의 물건을 느낍니다.","mis":"K3-1-u3-X06"},{"t":"바람이 부는 쪽도 수염으로 알아챕니다.","mis":"K3-1-u3-X06"}],"explanation":["쓸모가 많다","다른 문장을 묶어요","중심 문장"],"asset":{"type":"passage","lines":["고양이의 수염은 쓸모가 많습니다.","고양이는 수염으로 좁은 틈을 지나갈 수 있는지 잽니다.","어두운 곳에서는 수염으로 둘레의 물건을 느낍니다.","바람이 부는 쪽도 수염으로 알아챕니다."],"title":"고양이의 수염"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
