INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u3_L02_basic#9','kor',3,1,'u3','L02','g3_1_kor_u3_L02_basic','lesson_basic','K3-1-u3-C2',2,'mc','auto','짜임새 있는 글의 좋은 점은 무엇일까요?',ARRAY['K3-1-u3-X01','K3-1-u3-X02','K3-1-u3-X03']::text[],false,'{"seq":9,"concept":"K3-1-u3-C2","difficulty":2,"kind":"mc","stem":"짜임새 있는 글의 좋은 점은 무엇일까요?","options":[{"t":"생각이 또렷하게 드러나 읽는 사람이 쉽게 이해해요.","correct":true},{"t":"생각나는 대로 써서 빨리 쓸 수 있어요.","mis":"K3-1-u3-X01"},{"t":"문장마다 줄을 바꾸어 글이 길어 보여요.","mis":"K3-1-u3-X02"},{"t":"여러 생각이 섞여 있어 읽는 재미가 있어요.","mis":"K3-1-u3-X03"}],"explanation":["또렷한 생각","자연스러운 이음","쉽게 이해"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u3_L02_basic#10','kor',3,1,'u3','L02','g3_1_kor_u3_L02_basic','lesson_basic','K3-1-u3-C8',3,'mc','auto','「겨울을 나는 동물」의 중심 문장은 어느 자리에 있을까요?',ARRAY['K3-1-u3-X05','K3-1-u3-X11','K3-1-u3-X06']::text[],false,'{"seq":10,"concept":"K3-1-u3-C8","difficulty":3,"kind":"mc","stem":"「겨울을 나는 동물」의 중심 문장은 어느 자리에 있을까요?","options":[{"t":"문단의 끝","correct":true},{"t":"문단의 맨 앞 — 중심 문장은 언제나 앞에 와요","mis":"K3-1-u3-X05"},{"t":"없어요 — 중심 문장이 없는 문단이에요","mis":"K3-1-u3-X11"},{"t":"셋째 문장 — 박쥐 이야기가 가장 재미있어요","mis":"K3-1-u3-X06"}],"explanation":["이렇게","모아 정리","끝에 와요"],"asset":{"type":"passage","lines":["개구리는 땅속에 들어가 겨울을 납니다.","곰은 깊은 굴속에서 겨울을 보냅니다.","박쥐는 동굴 천장에 거꾸로 매달려 잠을 잡니다.","이렇게 추운 겨울 동안 잠을 자며 지내는 동물이 많습니다."],"title":"겨울을 나는 동물"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u3_L02_challenge#1','kor',3,1,'u3','L02','g3_1_kor_u3_L02_challenge','lesson_challenge','K3-1-u3-C7',2,'mc','auto','중심 문장을 찾는 방법으로 알맞은 것은 무엇일까요?',ARRAY['K3-1-u3-X04','K3-1-u3-X05','K3-1-u3-X06']::text[],false,'{"seq":1,"concept":"K3-1-u3-C7","difficulty":2,"kind":"mc","stem":"중심 문장을 찾는 방법으로 알맞은 것은 무엇일까요?","options":[{"t":"다른 문장의 내용을 모두 묶어 주는 문장을 찾는다.","correct":true},{"t":"가장 긴 문장을 찾는다.","mis":"K3-1-u3-X04"},{"t":"언제나 첫 문장을 고른다.","mis":"K3-1-u3-X05"},{"t":"예가 가장 재미있는 문장을 고른다.","mis":"K3-1-u3-X06"}],"explanation":["길이가 아니라","모두 묶는","문장"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u3_L02_challenge#2','kor',3,1,'u3','L02','g3_1_kor_u3_L02_challenge','lesson_challenge','K3-1-u3-C6',2,'mc','auto','새 문단을 시작할 때 어떻게 쓸까요?',ARRAY['K3-1-u3-X07','K3-1-u3-X02']::text[],false,'{"seq":2,"concept":"K3-1-u3-C6","difficulty":2,"kind":"mc","stem":"새 문단을 시작할 때 어떻게 쓸까요?","options":[{"t":"줄을 바꾸고 한 칸 들여 써요.","correct":true},{"t":"줄을 바꾸지 않고 앞 문단에 이어 써요.","mis":"K3-1-u3-X07"},{"t":"문장 하나마다 새 문단으로 써요.","mis":"K3-1-u3-X02"},{"t":"들여 쓰지 않고 첫 칸부터 써요.","mis":"K3-1-u3-X07"}],"explanation":["새 문단","줄 바꿈","한 칸 들여"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u3_L02_challenge#3','kor',3,1,'u3','L02','g3_1_kor_u3_L02_challenge','lesson_challenge','K3-1-u3-C4',3,'mc','auto','「겨울을 나는 동물」의 중심 문장은 무엇일까요?',ARRAY['K3-1-u3-X05','K3-1-u3-X06']::text[],false,'{"seq":3,"concept":"K3-1-u3-C4","difficulty":3,"kind":"mc","stem":"「겨울을 나는 동물」의 중심 문장은 무엇일까요?","options":[{"t":"이렇게 추운 겨울 동안 잠을 자며 지내는 동물이 많습니다.","correct":true},{"t":"개구리는 땅속에 들어가 겨울을 납니다.","mis":"K3-1-u3-X05"},{"t":"박쥐는 동굴 천장에 거꾸로 매달려 잠을 잡니다.","mis":"K3-1-u3-X06"},{"t":"곰은 깊은 굴속에서 겨울을 보냅니다.","mis":"K3-1-u3-X06"}],"explanation":["개구리 · 곰 · 박쥐","모두 묶는","끝 문장"],"asset":{"type":"passage","lines":["개구리는 땅속에 들어가 겨울을 납니다.","곰은 깊은 굴속에서 겨울을 보냅니다.","박쥐는 동굴 천장에 거꾸로 매달려 잠을 잡니다.","이렇게 추운 겨울 동안 잠을 자며 지내는 동물이 많습니다."],"title":"겨울을 나는 동물"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u3_L02_challenge#4','kor',3,1,'u3','L02','g3_1_kor_u3_L02_challenge','lesson_challenge','K3-1-u3-C8',3,'mc','auto','중심 문장의 자리에 대해 바르게 말한 것은 무엇일까요?',ARRAY['K3-1-u3-X05','K3-1-u3-X04']::text[],false,'{"seq":4,"concept":"K3-1-u3-C8","difficulty":3,"kind":"mc","stem":"중심 문장의 자리에 대해 바르게 말한 것은 무엇일까요?","options":[{"t":"앞에 올 때가 많지만 가운데나 끝에 올 수도 있어요.","correct":true},{"t":"언제나 맨 앞에만 와요.","mis":"K3-1-u3-X05"},{"t":"언제나 맨 끝에만 와요.","mis":"K3-1-u3-X05"},{"t":"가장 긴 문장이 있는 자리에 와요.","mis":"K3-1-u3-X04"}],"explanation":["앞","가운데","끝"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u3_L02_challenge#5','kor',3,1,'u3','L02','g3_1_kor_u3_L02_challenge','lesson_challenge','K3-1-u3-C3',3,'mc','auto','한 문단으로 묶기에 가장 알맞은 것은 무엇일까요?',ARRAY['K3-1-u3-X03','K3-1-u3-X11','K3-1-u3-X02']::text[],false,'{"seq":5,"concept":"K3-1-u3-C3","difficulty":3,"kind":"mc","stem":"한 문단으로 묶기에 가장 알맞은 것은 무엇일까요?","options":[{"t":"비 오는 날은 챙길 것이 많습니다. 우산을 챙깁니다. 장화도 신습니다.","correct":true},{"t":"비 오는 날은 챙길 것이 많습니다. 내 동생은 일곱 살입니다. 어제 짜장면을 먹었습니다.","mis":"K3-1-u3-X03"},{"t":"비 오는 날은 챙길 것이 많습니다.","mis":"K3-1-u3-X11"},{"t":"우산을 챙깁니다. / 장화를 신습니다. — 문장마다 한 문단씩","mis":"K3-1-u3-X02"}],"explanation":["한 가지 생각","중심 + 뒷받침","한 문단"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u3_L02_challenge#6','kor',3,1,'u3','L02','g3_1_kor_u3_L02_challenge','lesson_challenge','K3-1-u3-C5',3,'mc','auto','「고양이의 수염」에 뒷받침 문장을 하나 더 넣는다면 알맞은 것은 무엇일까요?',ARRAY['K3-1-u3-X09','K3-1-u3-X08']::text[],false,'{"seq":6,"concept":"K3-1-u3-C5","difficulty":3,"kind":"mc","stem":"「고양이의 수염」에 뒷받침 문장을 하나 더 넣는다면 알맞은 것은 무엇일까요?","options":[{"t":"수염에 무엇이 닿으면 고양이는 가까이에 무엇이 있는지 알아챕니다.","correct":true},{"t":"고양이는 털 색깔이 여러 가지입니다.","mis":"K3-1-u3-X09"},{"t":"고양이의 수염은 쓸모가 많고 많습니다.","mis":"K3-1-u3-X08"},{"t":"우리 집 강아지는 산책을 좋아합니다.","mis":"K3-1-u3-X09"}],"explanation":["수염의 쓸모","또 하나의 예","되풀이 ✗"],"asset":{"type":"passage","lines":["고양이의 수염은 쓸모가 많습니다.","고양이는 수염으로 좁은 틈을 지나갈 수 있는지 잽니다.","어두운 곳에서는 수염으로 둘레의 물건을 느낍니다.","바람이 부는 쪽도 수염으로 알아챕니다."],"title":"고양이의 수염"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u3_L02_challenge#7','kor',3,1,'u3','L02','g3_1_kor_u3_L02_challenge','lesson_challenge','K3-1-u3-C7',3,'mc','auto','「우리 동네 시장」에서 다른 문장을 모두 묶어 주는 문장은 무엇일까요?',ARRAY['K3-1-u3-X04','K3-1-u3-X06']::text[],false,'{"seq":7,"concept":"K3-1-u3-C7","difficulty":3,"kind":"mc","stem":"「우리 동네 시장」에서 다른 문장을 모두 묶어 주는 문장은 무엇일까요?","options":[{"t":"우리 동네 시장에는 맛있는 먹거리가 많습니다.","correct":true},{"t":"시장 끝 가게에서는 따끈한 어묵 국물 냄새가 납니다.","mis":"K3-1-u3-X04"},{"t":"떡집에는 알록달록한 떡이 줄지어 놓여 있습니다.","mis":"K3-1-u3-X06"},{"t":"시장 입구에서는 갓 구운 붕어빵을 팝니다.","mis":"K3-1-u3-X06"}],"explanation":["붕어빵 · 떡 · 어묵","먹거리","묶는 문장"],"asset":{"type":"passage","lines":["우리 동네 시장에는 맛있는 먹거리가 많습니다.","시장 입구에서는 갓 구운 붕어빵을 팝니다.","떡집에는 알록달록한 떡이 줄지어 놓여 있습니다.","시장 끝 가게에서는 따끈한 어묵 국물 냄새가 납니다."],"title":"우리 동네 시장"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u3_L02_challenge#8','kor',3,1,'u3','L02','g3_1_kor_u3_L02_challenge','lesson_challenge','K3-1-u3-C4',4,'essay','teacher','「고양이의 수염」의 중심 문장을 찾아 쓰고, 그 문장이 중심 문장인 까닭을 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K3-1-u3-C4","difficulty":4,"kind":"essay","stem":"「고양이의 수염」의 중심 문장을 찾아 쓰고, 그 문장이 중심 문장인 까닭을 쓰세요.","answer_guide":{"answer":"예: 중심 문장은 「고양이의 수염은 쓸모가 많습니다.」이다. 나머지 세 문장이 틈 재기 · 어둠 속에서 느끼기 · 바람 알아채기처럼 수염의 쓸모를 하나씩 말하고, 이 문장이 그것을 모두 묶어 주기 때문이다.","scoring_points":["중심 문장을 바르게 찾았는가","나머지 문장이 쓸모의 예임을 썼는가","모두 묶어 준다는 까닭을 썼는가"]},"explanation":["중심 문장","예","묶어 주는 까닭"],"asset":{"type":"passage","lines":["고양이의 수염은 쓸모가 많습니다.","고양이는 수염으로 좁은 틈을 지나갈 수 있는지 잽니다.","어두운 곳에서는 수염으로 둘레의 물건을 느낍니다.","바람이 부는 쪽도 수염으로 알아챕니다."],"title":"고양이의 수염"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u3_L02_challenge#9','kor',3,1,'u3','L02','g3_1_kor_u3_L02_challenge','lesson_challenge','K3-1-u3-C8',4,'essay','teacher','「겨울을 나는 동물」의 중심 문장을 맨 앞으로 옮겨 문단을 다시 쓰고, 중심 문장이 앞에 올 때와 끝에 올 때 어떻게 다른지 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K3-1-u3-C8","difficulty":4,"kind":"essay","stem":"「겨울을 나는 동물」의 중심 문장을 맨 앞으로 옮겨 문단을 다시 쓰고, 중심 문장이 앞에 올 때와 끝에 올 때 어떻게 다른지 쓰세요.","answer_guide":{"answer":"예: 추운 겨울 동안 잠을 자며 지내는 동물이 많습니다. 개구리는 땅속에 들어가 겨울을 납니다. 곰은 깊은 굴속에서 겨울을 보냅니다. 박쥐는 동굴 천장에 거꾸로 매달려 잠을 잡니다. 앞에 오면 무엇을 말할지 먼저 알 수 있고, 끝에 오면 예를 다 읽은 뒤 생각을 모아 정리해 준다.","scoring_points":["중심 문장을 맨 앞에 두고 「이렇게」를 알맞게 고쳤는가","뒷받침 문장을 빠짐없이 옮겼는가","앞과 끝의 차이를 썼는가"]},"explanation":["앞으로 옮기기","뒷받침 그대로","차이"],"asset":{"type":"passage","lines":["개구리는 땅속에 들어가 겨울을 납니다.","곰은 깊은 굴속에서 겨울을 보냅니다.","박쥐는 동굴 천장에 거꾸로 매달려 잠을 잡니다.","이렇게 추운 겨울 동안 잠을 자며 지내는 동물이 많습니다."],"title":"겨울을 나는 동물"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u3_L02_challenge#10','kor',3,1,'u3','L02','g3_1_kor_u3_L02_challenge','lesson_challenge','K3-1-u3-C6',4,'essay','teacher','문단을 쓸 때 지켜야 할 약속 두 가지를 쓰고, 지키지 않으면 어떤 일이 생기는지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K3-1-u3-C6","difficulty":4,"kind":"essay","stem":"문단을 쓸 때 지켜야 할 약속 두 가지를 쓰고, 지키지 않으면 어떤 일이 생기는지 쓰세요.","answer_guide":{"answer":"예: 문단을 시작할 때 한 칸 들여 쓴다. 새 문단은 줄을 바꾸어 쓴다. 지키지 않으면 어디서 새 생각이 시작되는지 알기 어려워 글을 읽기 힘들다.","scoring_points":["들여쓰기를 썼는가","줄 바꾸기나 한 문단 한 생각을 썼는가","지키지 않을 때 생기는 일을 썼는가"]},"explanation":["들여쓰기","줄 바꿈","읽기 어려워요"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u3_L04_basic#1','kor',3,1,'u3','L04','g3_1_kor_u3_L04_basic','lesson_basic','K3-1-u3-C9',1,'mc','auto','어울리는 뒷받침 문장은 어떤 문장일까요?',ARRAY['K3-1-u3-X09','K3-1-u3-X08']::text[],false,'{"seq":1,"concept":"K3-1-u3-C9","difficulty":1,"kind":"mc","stem":"어울리는 뒷받침 문장은 어떤 문장일까요?","options":[{"t":"중심 문장과 같은 생각을 자세히 말하는 문장","correct":true},{"t":"중심 문장과 관계없는 재미있는 문장","mis":"K3-1-u3-X09"},{"t":"중심 문장을 그대로 한 번 더 쓴 문장","mis":"K3-1-u3-X08"},{"t":"글쓴이가 가장 좋아하는 것을 말하는 문장","mis":"K3-1-u3-X09"}],"explanation":["같은 생각","자세히","어울림"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u3_L04_basic#2','kor',3,1,'u3','L04','g3_1_kor_u3_L04_basic','lesson_basic','K3-1-u3-C10',1,'mc','auto','「우리 집 베란다」에서 중심 문장과 어울리지 않는 문장은 무엇일까요?',ARRAY['K3-1-u3-X09','K3-1-u3-X03']::text[],false,'{"seq":2,"concept":"K3-1-u3-C10","difficulty":1,"kind":"mc","stem":"「우리 집 베란다」에서 중심 문장과 어울리지 않는 문장은 무엇일까요?","options":[{"t":"나는 축구를 잘합니다.","correct":true},{"t":"상추가 넓은 잎을 펼칩니다.","mis":"K3-1-u3-X09"},{"t":"방울토마토가 빨갛게 익어 갑니다.","mis":"K3-1-u3-X09"},{"t":"고추는 하얀 꽃을 피웠습니다.","mis":"K3-1-u3-X03"}],"explanation":["베란다 채소","축구는","관계없어요"],"asset":{"type":"passage","lines":["우리 집 베란다에서는 여러 가지 채소가 자랍니다.","상추가 넓은 잎을 펼칩니다.","방울토마토가 빨갛게 익어 갑니다.","고추는 하얀 꽃을 피웠습니다.","나는 축구를 잘합니다."],"title":"우리 집 베란다"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u3_L04_basic#3','kor',3,1,'u3','L04','g3_1_kor_u3_L04_basic','lesson_basic','K3-1-u3-C11',1,'mc','auto','문단을 쓰기 전에 가장 먼저 정할 것은 무엇일까요?',ARRAY['K3-1-u3-X13','K3-1-u3-X12']::text[],false,'{"seq":3,"concept":"K3-1-u3-C11","difficulty":1,"kind":"mc","stem":"문단을 쓰기 전에 가장 먼저 정할 것은 무엇일까요?","options":[{"t":"무엇을 말할지 — 중심 문장","correct":true},{"t":"쓸 글자 수","mis":"K3-1-u3-X13"},{"t":"쓸 문장의 개수만","mis":"K3-1-u3-X12"},{"t":"아무것도 정하지 않고 바로 쓴다","mis":"K3-1-u3-X12"}],"explanation":["먼저","무엇을 말할지","중심 문장"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u3_L04_basic#4','kor',3,1,'u3','L04','g3_1_kor_u3_L04_basic','lesson_basic','K3-1-u3-C12',1,'mc','auto','중심 문장 하나만 쓰면 어떻게 될까요?',ARRAY['K3-1-u3-X11','K3-1-u3-X09']::text[],false,'{"seq":4,"concept":"K3-1-u3-C12","difficulty":1,"kind":"mc","stem":"중심 문장 하나만 쓰면 어떻게 될까요?","options":[{"t":"자세한 내용이 없어 생각이 잘 전해지지 않아요.","correct":true},{"t":"그것만으로 훌륭한 문단이 돼요.","mis":"K3-1-u3-X11"},{"t":"뒷받침 문장은 아무것이나 붙이면 돼요.","mis":"K3-1-u3-X09"},{"t":"문단이 더 짜임새 있어져요.","mis":"K3-1-u3-X11"}],"explanation":["중심만","자세한 내용 없음","뒷받침 필요"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u3_L04_basic#5','kor',3,1,'u3','L04','g3_1_kor_u3_L04_basic','lesson_basic','K3-1-u3-C10',2,'mc','auto','「나는 축구를 잘합니다.」를 「우리 집 베란다」에 어울리게 바꾼 문장은 무엇일까요?',ARRAY['K3-1-u3-X10','K3-1-u3-X08']::text[],false,'{"seq":5,"concept":"K3-1-u3-C10","difficulty":2,"kind":"mc","stem":"「나는 축구를 잘합니다.」를 「우리 집 베란다」에 어울리게 바꾼 문장은 무엇일까요?","options":[{"t":"오이 덩굴이 창틀을 타고 올라갑니다.","correct":true},{"t":"나는 축구보다 야구를 더 잘합니다.","mis":"K3-1-u3-X10"},{"t":"우리 반은 내일 소풍을 갑니다.","mis":"K3-1-u3-X10"},{"t":"우리 집 베란다에서는 여러 가지 채소가 자랍니다.","mis":"K3-1-u3-X08"}],"explanation":["채소 이야기로","바꾸기","되풀이 ✗"],"asset":{"type":"passage","lines":["우리 집 베란다에서는 여러 가지 채소가 자랍니다.","상추가 넓은 잎을 펼칩니다.","방울토마토가 빨갛게 익어 갑니다.","고추는 하얀 꽃을 피웠습니다.","나는 축구를 잘합니다."],"title":"우리 집 베란다"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u3_L04_basic#6','kor',3,1,'u3','L04','g3_1_kor_u3_L04_basic','lesson_basic','K3-1-u3-C9',2,'mc','auto','「우리 동네 시장에는 맛있는 먹거리가 많습니다.」와 어울리는 뒷받침 문장은 무엇일까요?',ARRAY['K3-1-u3-X09','K3-1-u3-X08']::text[],false,'{"seq":6,"concept":"K3-1-u3-C9","difficulty":2,"kind":"mc","stem":"「우리 동네 시장에는 맛있는 먹거리가 많습니다.」와 어울리는 뒷받침 문장은 무엇일까요?","options":[{"t":"반찬 가게에는 갓 무친 나물이 있습니다.","correct":true},{"t":"시장 옆에는 큰 주차장이 있습니다.","mis":"K3-1-u3-X09"},{"t":"나는 시장에 자주 가지 않습니다.","mis":"K3-1-u3-X09"},{"t":"우리 동네 시장에는 먹거리가 아주 많습니다.","mis":"K3-1-u3-X08"}],"explanation":["먹거리","예를 들어","어울림"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u3_L04_basic#7','kor',3,1,'u3','L04','g3_1_kor_u3_L04_basic','lesson_basic','K3-1-u3-C9',2,'match','auto','중심 문장과 어울리는 뒷받침 문장을 이으세요.','{}'::text[],false,'{"seq":7,"concept":"K3-1-u3-C9","difficulty":2,"kind":"match","stem":"중심 문장과 어울리는 뒷받침 문장을 이으세요.","pairs":[{"l":"우리 동네 공원은 쉬기 좋습니다.","r":"나무 그늘 아래 긴 의자가 많습니다."},{"l":"우리 동네 도서관은 책이 많습니다.","r":"그림책 방에만 책장이 열 개입니다."},{"l":"우리 동네 놀이터는 신납니다.","r":"길고 구불구불한 미끄럼틀이 있습니다."}],"mis":"K3-1-u3-X09","explanation":["쉬기 좋다","책이 많다","신난다"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u3_L04_basic#8','kor',3,1,'u3','L04','g3_1_kor_u3_L04_basic','lesson_basic','K3-1-u3-C13',2,'mc','auto','쓴 문단을 스스로 점검하는 물음으로 알맞은 것은 무엇일까요?',ARRAY['K3-1-u3-X13','K3-1-u3-X09']::text[],false,'{"seq":8,"concept":"K3-1-u3-C13","difficulty":2,"kind":"mc","stem":"쓴 문단을 스스로 점검하는 물음으로 알맞은 것은 무엇일까요?","options":[{"t":"뒷받침 문장이 중심 문장과 어울리나요?","correct":true},{"t":"글자가 몇 개인가요?","mis":"K3-1-u3-X13"},{"t":"친구 글보다 길게 썼나요?","mis":"K3-1-u3-X13"},{"t":"관계없는 문장을 더 넣었나요?","mis":"K3-1-u3-X09"}],"explanation":["중심","뒷받침","점검"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u3_L04_basic#9','kor',3,1,'u3','L04','g3_1_kor_u3_L04_basic','lesson_basic','K3-1-u3-C12',2,'mc','auto','「우리 반 텃밭은 정말 좋습니다.」 한 문장만 쓴 친구에게 해 줄 말로 알맞은 것은 무엇일까요?',ARRAY['K3-1-u3-X11','K3-1-u3-X08','K3-1-u3-X09']::text[],false,'{"seq":9,"concept":"K3-1-u3-C12","difficulty":2,"kind":"mc","stem":"「우리 반 텃밭은 정말 좋습니다.」 한 문장만 쓴 친구에게 해 줄 말로 알맞은 것은 무엇일까요?","options":[{"t":"「왜 좋은지 뒷받침 문장을 더 써 보자.」","correct":true},{"t":"「한 문장이면 문단으로 충분해.」","mis":"K3-1-u3-X11"},{"t":"「같은 문장을 한 번 더 쓰면 돼.」","mis":"K3-1-u3-X08"},{"t":"「좋아하는 놀이 이야기를 이어 쓰면 돼.」","mis":"K3-1-u3-X09"}],"explanation":["왜 좋은지","뒷받침","더 쓰기"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u3_L04_basic#10','kor',3,1,'u3','L04','g3_1_kor_u3_L04_basic','lesson_basic','K3-1-u3-C11',3,'mc','auto','「우리 학교 급식」을 소개하는 문단을 쓰려고 해요. 계획하는 차례로 알맞은 것은 무엇일까요?',ARRAY['K3-1-u3-X12','K3-1-u3-X13']::text[],false,'{"seq":10,"concept":"K3-1-u3-C11","difficulty":3,"kind":"mc","stem":"「우리 학교 급식」을 소개하는 문단을 쓰려고 해요. 계획하는 차례로 알맞은 것은 무엇일까요?","options":[{"t":"중심 문장 정하기 → 자세한 내용 떠올리기 → 어울리게 이어 쓰기","correct":true},{"t":"바로 쓰기 → 쓰다가 떠오르는 대로 바꾸기","mis":"K3-1-u3-X12"},{"t":"아무 내용이나 쓰기 → 다 쓰고 나서 중심 정하기","mis":"K3-1-u3-X12"},{"t":"글자 수 정하기 → 그만큼 채우기","mis":"K3-1-u3-X13"}],"explanation":["중심 먼저","내용 떠올리기","이어 쓰기"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u3_L04_challenge#1','kor',3,1,'u3','L04','g3_1_kor_u3_L04_challenge','lesson_challenge','K3-1-u3-C10',2,'mc','auto','중심 문장과 어울리지 않는 문장을 찾았을 때 알맞게 하는 방법은 무엇일까요?',ARRAY['K3-1-u3-X09','K3-1-u3-X10','K3-1-u3-X06']::text[],false,'{"seq":1,"concept":"K3-1-u3-C10","difficulty":2,"kind":"mc","stem":"중심 문장과 어울리지 않는 문장을 찾았을 때 알맞게 하는 방법은 무엇일까요?","options":[{"t":"빼거나 중심 생각에 맞는 문장으로 바꿔요.","correct":true},{"t":"그대로 두어도 문단이 길어지니 좋아요.","mis":"K3-1-u3-X09"},{"t":"또 다른 관계없는 문장으로 바꿔요.","mis":"K3-1-u3-X10"},{"t":"중심 문장을 지워 버려요.","mis":"K3-1-u3-X06"}],"explanation":["빼기","바꾸기","중심 생각에 맞게"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u3_L04_challenge#2','kor',3,1,'u3','L04','g3_1_kor_u3_L04_challenge','lesson_challenge','K3-1-u3-C13',2,'mc','auto','「한 칸 들여 썼나요?」는 무엇을 점검하는 물음일까요?',ARRAY['K3-1-u3-X13']::text[],false,'{"seq":2,"concept":"K3-1-u3-C13","difficulty":2,"kind":"mc","stem":"「한 칸 들여 썼나요?」는 무엇을 점검하는 물음일까요?","options":[{"t":"문단을 쓰는 약속을 지켰는지","correct":true},{"t":"뒷받침 문장이 어울리는지","mis":"K3-1-u3-X13"},{"t":"글자 수가 많은지","mis":"K3-1-u3-X13"},{"t":"재미있는 낱말을 썼는지","mis":"K3-1-u3-X13"}],"explanation":["들여쓰기","약속","점검"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u3_L04_challenge#3','kor',3,1,'u3','L04','g3_1_kor_u3_L04_challenge','lesson_challenge','K3-1-u3-C9',3,'mc','auto','「우리 집 베란다」에서 어울리는 뒷받침 문장들이 공통으로 말하는 것은 무엇일까요?',ARRAY['K3-1-u3-X09','K3-1-u3-X03']::text[],false,'{"seq":3,"concept":"K3-1-u3-C9","difficulty":3,"kind":"mc","stem":"「우리 집 베란다」에서 어울리는 뒷받침 문장들이 공통으로 말하는 것은 무엇일까요?","options":[{"t":"베란다에서 자라는 채소의 모습","correct":true},{"t":"글쓴이가 잘하는 운동","mis":"K3-1-u3-X09"},{"t":"베란다의 넓이","mis":"K3-1-u3-X03"},{"t":"채소를 맛있게 먹는 방법","mis":"K3-1-u3-X03"}],"explanation":["상추 · 토마토 · 고추","자라는 모습","공통"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u3_L04_challenge#4','kor',3,1,'u3','L04','g3_1_kor_u3_L04_challenge','lesson_challenge','K3-1-u3-C12',3,'mc','auto','뒷받침 문장을 여러 개 쓰는 까닭은 무엇일까요?',ARRAY['K3-1-u3-X01','K3-1-u3-X08','K3-1-u3-X09']::text[],false,'{"seq":4,"concept":"K3-1-u3-C12","difficulty":3,"kind":"mc","stem":"뒷받침 문장을 여러 개 쓰는 까닭은 무엇일까요?","options":[{"t":"중심 생각을 여러 가지로 자세히 보여 주면 읽는 사람이 잘 알 수 있어서","correct":true},{"t":"문단을 길어 보이게 하려고","mis":"K3-1-u3-X01"},{"t":"중심 문장을 여러 번 되풀이하려고","mis":"K3-1-u3-X08"},{"t":"관계없는 이야기도 넣으려고","mis":"K3-1-u3-X09"}],"explanation":["여러 가지","자세히","잘 전해져요"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u3_L04_challenge#5','kor',3,1,'u3','L04','g3_1_kor_u3_L04_challenge','lesson_challenge','K3-1-u3-C10',3,'mc','auto','「겨울에는 따뜻한 옷차림이 필요합니다. 두꺼운 외투를 입습니다. 털모자를 씁니다. 수영복을 챙깁니다.」에서 어울리지 않는 문장은 무엇일까요?',ARRAY['K3-1-u3-X09','K3-1-u3-X06']::text[],false,'{"seq":5,"concept":"K3-1-u3-C10","difficulty":3,"kind":"mc","stem":"「겨울에는 따뜻한 옷차림이 필요합니다. 두꺼운 외투를 입습니다. 털모자를 씁니다. 수영복을 챙깁니다.」에서 어울리지 않는 문장은 무엇일까요?","options":[{"t":"수영복을 챙깁니다.","correct":true},{"t":"두꺼운 외투를 입습니다.","mis":"K3-1-u3-X09"},{"t":"털모자를 씁니다.","mis":"K3-1-u3-X09"},{"t":"겨울에는 따뜻한 옷차림이 필요합니다.","mis":"K3-1-u3-X06"}],"explanation":["따뜻한 옷차림","수영복은","관계없어요"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u3_L04_challenge#6','kor',3,1,'u3','L04','g3_1_kor_u3_L04_challenge','lesson_challenge','K3-1-u3-C11',3,'mc','auto','계획 없이 쓰기 시작한 글에서 생기기 쉬운 일은 무엇일까요?',ARRAY['K3-1-u3-X12','K3-1-u3-X09','K3-1-u3-X07']::text[],false,'{"seq":6,"concept":"K3-1-u3-C11","difficulty":3,"kind":"mc","stem":"계획 없이 쓰기 시작한 글에서 생기기 쉬운 일은 무엇일까요?","options":[{"t":"쓰다가 중심 생각이 바뀌어 문장들이 따로 놀아요.","correct":true},{"t":"계획하지 않아도 언제나 짜임새가 좋아요.","mis":"K3-1-u3-X12"},{"t":"뒷받침 문장이 저절로 어울려요.","mis":"K3-1-u3-X09"},{"t":"들여쓰기를 저절로 하게 돼요.","mis":"K3-1-u3-X07"}],"explanation":["계획 없이","중심이 바뀜","따로 놀아요"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u3_L04_challenge#7','kor',3,1,'u3','L04','g3_1_kor_u3_L04_challenge','lesson_challenge','K3-1-u3-C13',3,'mc','auto','도하는 「우리 동네 놀이터」 문단을 쓰고 점검표를 채웠어요. 점검을 알맞게 마친 모습은 무엇일까요?',ARRAY['K3-1-u3-X13','K3-1-u3-X09']::text[],false,'{"seq":7,"concept":"K3-1-u3-C13","difficulty":3,"kind":"mc","stem":"도하는 「우리 동네 놀이터」 문단을 쓰고 점검표를 채웠어요. 점검을 알맞게 마친 모습은 무엇일까요?","options":[{"t":"중심 문장 ✓ · 어울리는 뒷받침 문장 ✓ · 한 칸 들여쓰기 ✓","correct":true},{"t":"글자 수 ✓ 하나만 확인했어요.","mis":"K3-1-u3-X13"},{"t":"점검 없이 바로 냈어요.","mis":"K3-1-u3-X13"},{"t":"중심 문장 ✓ · 관계없는 문장도 그대로 두었어요.","mis":"K3-1-u3-X09"}],"explanation":["세 가지","빠짐없이","점검"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u3_L04_challenge#8','kor',3,1,'u3','L04','g3_1_kor_u3_L04_challenge','lesson_challenge','K3-1-u3-C10',4,'essay','teacher','「우리 집 베란다」에서 어울리지 않는 문장을 찾아 쓰고, 어울리는 문장으로 바꾸어 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K3-1-u3-C10","difficulty":4,"kind":"essay","stem":"「우리 집 베란다」에서 어울리지 않는 문장을 찾아 쓰고, 어울리는 문장으로 바꾸어 쓰세요.","answer_guide":{"answer":"예: 「나는 축구를 잘합니다.」는 베란다에서 자라는 채소와 관계없다. 「작은 화분에서는 깻잎이 쑥쑥 자랍니다.」로 바꾼다.","scoring_points":["어울리지 않는 문장을 찾았는가","바꾼 문장이 베란다 채소 이야기인가","중심 문장을 되풀이하지 않았는가"]},"explanation":["찾기","바꾸기","채소 이야기"],"asset":{"type":"passage","lines":["우리 집 베란다에서는 여러 가지 채소가 자랍니다.","상추가 넓은 잎을 펼칩니다.","방울토마토가 빨갛게 익어 갑니다.","고추는 하얀 꽃을 피웠습니다.","나는 축구를 잘합니다."],"title":"우리 집 베란다"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u3_L04_challenge#9','kor',3,1,'u3','L04','g3_1_kor_u3_L04_challenge','lesson_challenge','K3-1-u3-C11',4,'essay','teacher','「우리 교실」을 소개하는 문단을 쓰려고 해요. 중심 문장을 정하고, 어울리는 뒷받침 내용 두 가지를 계획해 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K3-1-u3-C11","difficulty":4,"kind":"essay","stem":"「우리 교실」을 소개하는 문단을 쓰려고 해요. 중심 문장을 정하고, 어울리는 뒷받침 내용 두 가지를 계획해 쓰세요.","answer_guide":{"answer":"예: 중심 문장 — 우리 교실은 아늑합니다. 뒷받침 내용 — 창가에 화분이 줄지어 있다. 뒤쪽에 책을 읽는 푹신한 방석 자리가 있다.","scoring_points":["중심 문장을 정했는가","뒷받침 내용 두 가지를 썼는가","뒷받침 내용이 중심 문장과 어울리는가"]},"explanation":["중심 정하기","내용 둘","어울림"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u3_L04_challenge#10','kor',3,1,'u3','L04','g3_1_kor_u3_L04_challenge','lesson_challenge','K3-1-u3-C12',4,'essay','teacher','「우리 동네 시장」에 어울리는 뒷받침 문장을 하나 더 쓰고, 그 문장이 어울리는 까닭을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K3-1-u3-C12","difficulty":4,"kind":"essay","stem":"「우리 동네 시장」에 어울리는 뒷받침 문장을 하나 더 쓰고, 그 문장이 어울리는 까닭을 쓰세요.","answer_guide":{"answer":"예: 「과일 가게에는 달콤한 귤이 산처럼 쌓여 있습니다.」 시장에 있는 맛있는 먹거리의 예를 하나 더 들어 중심 문장을 자세히 설명하기 때문이다.","scoring_points":["뒷받침 문장을 썼는가","시장의 먹거리 이야기인가","어울리는 까닭을 썼는가"]},"explanation":["먹거리 예","하나 더","까닭"],"asset":{"type":"passage","lines":["우리 동네 시장에는 맛있는 먹거리가 많습니다.","시장 입구에서는 갓 구운 붕어빵을 팝니다.","떡집에는 알록달록한 떡이 줄지어 놓여 있습니다.","시장 끝 가게에서는 따끈한 어묵 국물 냄새가 납니다."],"title":"우리 동네 시장"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u3_L06_basic#1','kor',3,1,'u3','L06','g3_1_kor_u3_L06_basic','lesson_basic','K3-1-u3-C14',1,'mc','auto','작품을 읽고 「재미」를 느낀다는 것은 무엇일까요?',ARRAY['K3-1-u3-X14','K3-1-u3-X01','K3-1-u3-X15']::text[],false,'{"seq":1,"concept":"K3-1-u3-C14","difficulty":1,"kind":"mc","stem":"작품을 읽고 「재미」를 느낀다는 것은 무엇일까요?","options":[{"t":"웃음이 나거나 흥미로워 더 읽고 싶어지는 것","correct":true},{"t":"마음이 뭉클해 눈물이 날 것 같은 것만","mis":"K3-1-u3-X14"},{"t":"글자가 많아 오래 읽는 것","mis":"K3-1-u3-X01"},{"t":"뜻을 몰라 지루한 것","mis":"K3-1-u3-X15"}],"explanation":["웃음","흥미","재미"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u3_L06_basic#2','kor',3,1,'u3','L06','g3_1_kor_u3_L06_basic','lesson_basic','K3-1-u3-C15',1,'mc','auto','작품을 읽고 「감동」을 받는다는 것은 무엇일까요?',ARRAY['K3-1-u3-X14','K3-1-u3-X15','K3-1-u3-X16']::text[],false,'{"seq":2,"concept":"K3-1-u3-C15","difficulty":1,"kind":"mc","stem":"작품을 읽고 「감동」을 받는다는 것은 무엇일까요?","options":[{"t":"마음이 뭉클하거나 깊이 울리는 것","correct":true},{"t":"무조건 크게 웃는 것","mis":"K3-1-u3-X14"},{"t":"읽은 글자를 외우는 것","mis":"K3-1-u3-X15"},{"t":"작품과 관계없는 일을 떠올리는 것","mis":"K3-1-u3-X16"}],"explanation":["뭉클","깊이 울림","감동"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u3_L06_basic#3','kor',3,1,'u3','L06','g3_1_kor_u3_L06_basic','lesson_basic','K3-1-u3-C16',1,'mc','auto','시를 읽으며 재미나 감동을 느끼는 방법으로 알맞은 것은 무엇일까요?',ARRAY['K3-1-u3-X15','K3-1-u3-X17']::text[],false,'{"seq":3,"concept":"K3-1-u3-C16","difficulty":1,"kind":"mc","stem":"시를 읽으며 재미나 감동을 느끼는 방법으로 알맞은 것은 무엇일까요?","options":[{"t":"시에 나오는 장면을 눈앞에 그려 본다.","correct":true},{"t":"장면은 생각하지 않고 글자만 읽는다.","mis":"K3-1-u3-X15"},{"t":"뜻과 상관없이 가장 빠르게 읽는다.","mis":"K3-1-u3-X17"},{"t":"한 번 읽고 바로 덮는다.","mis":"K3-1-u3-X15"}],"explanation":["장면","눈앞에","그려 보기"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u3_L06_basic#4','kor',3,1,'u3','L06','g3_1_kor_u3_L06_basic','lesson_basic','K3-1-u3-C18',1,'mc','auto','시를 낭송할 때 알맞은 방법은 무엇일까요?',ARRAY['K3-1-u3-X17','K3-1-u3-X15']::text[],false,'{"seq":4,"concept":"K3-1-u3-C18","difficulty":1,"kind":"mc","stem":"시를 낭송할 때 알맞은 방법은 무엇일까요?","options":[{"t":"시의 마음을 살려 알맞은 빠르기로 읽는다.","correct":true},{"t":"가장 빠르게 읽는다.","mis":"K3-1-u3-X17"},{"t":"있는 힘껏 소리친다.","mis":"K3-1-u3-X17"},{"t":"뜻은 생각하지 않고 글자만 읽는다.","mis":"K3-1-u3-X15"}],"explanation":["시의 마음","알맞은 빠르기","낭송"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u3_L06_basic#5','kor',3,1,'u3','L06','g3_1_kor_u3_L06_basic','lesson_basic','K3-1-u3-C14',2,'mc','auto','「아빠 수염」에서 재미를 느낄 수 있는 까닭은 무엇일까요?',ARRAY['K3-1-u3-X14','K3-1-u3-X01','K3-1-u3-X15']::text[],false,'{"seq":5,"concept":"K3-1-u3-C14","difficulty":2,"kind":"mc","stem":"「아빠 수염」에서 재미를 느낄 수 있는 까닭은 무엇일까요?","options":[{"t":"「간질간질」, 「깔깔깔」 같은 말이 재미있고, 면도기가 샘낸다는 생각이 엉뚱해서","correct":true},{"t":"슬픈 일이 일어나서","mis":"K3-1-u3-X14"},{"t":"글자 수가 많아서","mis":"K3-1-u3-X01"},{"t":"아무 장면도 떠오르지 않아서","mis":"K3-1-u3-X15"}],"explanation":["흉내 내는 말","엉뚱한 생각","재미"],"asset":{"type":"passage","lines":["아빠가 볼에 뽀뽀하면","까슬까슬 수염이","간질간질 간지러워","나는 깔깔깔","아빠는 껄껄껄","면도기가 샘내겠다"],"title":"아빠 수염"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
