INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u3_L06_basic#10','kor',3,1,'u3','L06','g3_1_kor_u3_L06_basic','lesson_basic','K3-1-u3-C17',3,'mc','auto','「빈 의자」와 비슷한 경험으로 가장 알맞은 것은 무엇일까요?',ARRAY['K3-1-u3-X16']::text[],false,'{"seq":10,"concept":"K3-1-u3-C17","difficulty":3,"kind":"mc","stem":"「빈 의자」와 비슷한 경험으로 가장 알맞은 것은 무엇일까요?","options":[{"t":"친한 친구가 이사 가서 함께 놀던 자리가 허전했던 일","correct":true},{"t":"어제 저녁에 김밥을 맛있게 먹은 일","mis":"K3-1-u3-X16"},{"t":"새 의자를 선물 받아 신났던 일","mis":"K3-1-u3-X16"},{"t":"운동회에서 달리기 1등을 한 일","mis":"K3-1-u3-X16"}],"explanation":["떠난 친구","허전함","닮은 경험"],"asset":{"type":"passage","lines":["짝꿍이 전학 간 날","옆 의자가 텅 비었어요","지우개 빌려 달라고","쿡쿡 찌를 데가 없어요","비어 있는 의자만큼","보고 싶은 마음이 커져요"],"title":"빈 의자"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u3_L06_challenge#1','kor',3,1,'u3','L06','g3_1_kor_u3_L06_challenge','lesson_challenge','K3-1-u3-C20',2,'mc','auto','같은 시를 읽고 친구와 느낀 점이 다를 때 알맞은 생각은 무엇일까요?',ARRAY['K3-1-u3-X19','K3-1-u3-X18']::text[],false,'{"seq":1,"concept":"K3-1-u3-C20","difficulty":2,"kind":"mc","stem":"같은 시를 읽고 친구와 느낀 점이 다를 때 알맞은 생각은 무엇일까요?","options":[{"t":"사람마다 다르게 느낄 수 있으니 서로의 까닭을 들어 본다.","correct":true},{"t":"나와 다르게 느낀 친구는 잘못 읽은 것이다.","mis":"K3-1-u3-X19"},{"t":"선생님 느낌 하나만 맞는 느낌이다.","mis":"K3-1-u3-X19"},{"t":"다르게 느꼈다면 말하지 않는 것이 좋다.","mis":"K3-1-u3-X18"}],"explanation":["저마다","까닭","들어 보기"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u3_L06_challenge#2','kor',3,1,'u3','L06','g3_1_kor_u3_L06_challenge','lesson_challenge','K3-1-u3-C18',2,'mc','auto','「빈 의자」를 낭송할 때 어울리는 목소리는 무엇일까요?',ARRAY['K3-1-u3-X17','K3-1-u3-X14']::text[],false,'{"seq":2,"concept":"K3-1-u3-C18","difficulty":2,"kind":"mc","stem":"「빈 의자」를 낭송할 때 어울리는 목소리는 무엇일까요?","options":[{"t":"조금 느리고 차분한 목소리","correct":true},{"t":"아주 빠르고 신나는 목소리","mis":"K3-1-u3-X17"},{"t":"있는 힘껏 소리치는 목소리","mis":"K3-1-u3-X17"},{"t":"웃음을 터뜨리며 읽는 목소리","mis":"K3-1-u3-X14"}],"explanation":["그리움","느리고 차분하게","낭송"],"asset":{"type":"passage","lines":["짝꿍이 전학 간 날","옆 의자가 텅 비었어요","지우개 빌려 달라고","쿡쿡 찌를 데가 없어요","비어 있는 의자만큼","보고 싶은 마음이 커져요"],"title":"빈 의자"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u3_L06_challenge#3','kor',3,1,'u3','L06','g3_1_kor_u3_L06_challenge','lesson_challenge','K3-1-u3-C19',3,'mc','auto','태오의 발표를 듣고 해 줄 말로 알맞은 것은 무엇일까요?',ARRAY['K3-1-u3-X18','K3-1-u3-X26','K3-1-u3-X19']::text[],false,'{"seq":3,"concept":"K3-1-u3-C19","difficulty":3,"kind":"mc","stem":"태오의 발표를 듣고 해 줄 말로 알맞은 것은 무엇일까요?","options":[{"t":"「무엇 때문에 좋았는지 까닭도 말해 줄래?」","correct":true},{"t":"「좋았다는 말이면 충분해.」","mis":"K3-1-u3-X18"},{"t":"「하윤이가 한 말을 똑같이 하면 돼.」","mis":"K3-1-u3-X26"},{"t":"「느낌은 하나만 맞으니 다시 생각해.」","mis":"K3-1-u3-X19"}],"explanation":["좋았어","왜?","까닭"],"asset":{"type":"speech","turns":[{"who":"하윤","text":"나는 「빈 의자」의 마지막 두 줄에서 마음이 뭉클했어. 작년에 단짝이 이사 가서 나도 많이 보고 싶었거든."},{"who":"태오","text":"나는 「빈 의자」가 좋았어."},{"who":"서아","text":"나는 「아빠 수염」의 마지막 줄이 웃겼어. 면도기가 사람처럼 샘을 낸다니 엉뚱하잖아."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u3_L06_challenge#4','kor',3,1,'u3','L06','g3_1_kor_u3_L06_challenge','lesson_challenge','K3-1-u3-C17',3,'mc','auto','하윤이가 감상을 발표할 때 쓴 방법은 무엇일까요?',ARRAY['K3-1-u3-X16','K3-1-u3-X18','K3-1-u3-X26']::text[],false,'{"seq":4,"concept":"K3-1-u3-C17","difficulty":3,"kind":"mc","stem":"하윤이가 감상을 발표할 때 쓴 방법은 무엇일까요?","options":[{"t":"작품과 닮은 내 경험을 떠올려 까닭으로 말했다.","correct":true},{"t":"작품과 관계없는 이야기를 늘어놓았다.","mis":"K3-1-u3-X16"},{"t":"까닭 없이 느낌만 말했다.","mis":"K3-1-u3-X18"},{"t":"친구의 느낌을 그대로 따라 했다.","mis":"K3-1-u3-X26"}],"explanation":["단짝의 이사","닮은 경험","까닭"],"asset":{"type":"speech","turns":[{"who":"하윤","text":"나는 「빈 의자」의 마지막 두 줄에서 마음이 뭉클했어. 작년에 단짝이 이사 가서 나도 많이 보고 싶었거든."},{"who":"태오","text":"나는 「빈 의자」가 좋았어."},{"who":"서아","text":"나는 「아빠 수염」의 마지막 줄이 웃겼어. 면도기가 사람처럼 샘을 낸다니 엉뚱하잖아."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u3_L06_challenge#5','kor',3,1,'u3','L06','g3_1_kor_u3_L06_challenge','lesson_challenge','K3-1-u3-C14',3,'mc','auto','서아가 「아빠 수염」에서 느낀 것과 그 까닭으로 알맞은 것은 무엇일까요?',ARRAY['K3-1-u3-X14','K3-1-u3-X18']::text[],false,'{"seq":5,"concept":"K3-1-u3-C14","difficulty":3,"kind":"mc","stem":"서아가 「아빠 수염」에서 느낀 것과 그 까닭으로 알맞은 것은 무엇일까요?","options":[{"t":"재미 — 면도기가 사람처럼 샘낸다는 생각이 엉뚱해서","correct":true},{"t":"감동 — 아빠가 보고 싶어서","mis":"K3-1-u3-X14"},{"t":"재미 — 까닭은 말하지 않았어요","mis":"K3-1-u3-X18"},{"t":"감동 — 시가 길어서","mis":"K3-1-u3-X14"}],"explanation":["웃겼어","엉뚱함","재미"],"asset":{"type":"speech","turns":[{"who":"하윤","text":"나는 「빈 의자」의 마지막 두 줄에서 마음이 뭉클했어. 작년에 단짝이 이사 가서 나도 많이 보고 싶었거든."},{"who":"태오","text":"나는 「빈 의자」가 좋았어."},{"who":"서아","text":"나는 「아빠 수염」의 마지막 줄이 웃겼어. 면도기가 사람처럼 샘을 낸다니 엉뚱하잖아."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u3_L06_challenge#6','kor',3,1,'u3','L06','g3_1_kor_u3_L06_challenge','lesson_challenge','K3-1-u3-C16',3,'mc','auto','「아빠 수염」을 읽고 떠올린 장면으로 가장 알맞은 것은 무엇일까요?',ARRAY['K3-1-u3-X20','K3-1-u3-X15']::text[],false,'{"seq":6,"concept":"K3-1-u3-C16","difficulty":3,"kind":"mc","stem":"「아빠 수염」을 읽고 떠올린 장면으로 가장 알맞은 것은 무엇일까요?","options":[{"t":"아빠가 볼에 뽀뽀하자 아이가 간지러워 깔깔 웃는 모습","correct":true},{"t":"아빠가 면도기를 사러 가게에 가는 모습","mis":"K3-1-u3-X20"},{"t":"아이가 혼자 쓸쓸히 의자에 앉은 모습","mis":"K3-1-u3-X15"},{"t":"아빠와 아이가 서로 화가 난 모습","mis":"K3-1-u3-X15"}],"explanation":["뽀뽀","간지러움","깔깔"],"asset":{"type":"passage","lines":["아빠가 볼에 뽀뽀하면","까슬까슬 수염이","간질간질 간지러워","나는 깔깔깔","아빠는 껄껄껄","면도기가 샘내겠다"],"title":"아빠 수염"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u3_L06_challenge#7','kor',3,1,'u3','L06','g3_1_kor_u3_L06_challenge','lesson_challenge','K3-1-u3-C15',3,'mc','auto','재미와 감동에 대해 바르게 말한 친구의 말은 무엇일까요?',ARRAY['K3-1-u3-X14','K3-1-u3-X19']::text[],false,'{"seq":7,"concept":"K3-1-u3-C15","difficulty":3,"kind":"mc","stem":"재미와 감동에 대해 바르게 말한 친구의 말은 무엇일까요?","options":[{"t":"「웃겨서 좋은 작품도 있고, 뭉클해서 좋은 작품도 있어.」","correct":true},{"t":"「웃기지 않으면 좋은 작품이 아니야.」","mis":"K3-1-u3-X14"},{"t":"「재미와 감동은 같은 말이야.」","mis":"K3-1-u3-X14"},{"t":"「작품을 읽으면 모두 똑같이 느껴야 해.」","mis":"K3-1-u3-X19"}],"explanation":["재미","감동","둘 다 소중"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u3_L06_challenge#8','kor',3,1,'u3','L06','g3_1_kor_u3_L06_challenge','lesson_challenge','K3-1-u3-C19',4,'essay','teacher','「빈 의자」에서 감동을 느낀 부분을 하나 고르고, 그렇게 느낀 까닭을 비슷한 경험과 함께 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K3-1-u3-C19","difficulty":4,"kind":"essay","stem":"「빈 의자」에서 감동을 느낀 부분을 하나 고르고, 그렇게 느낀 까닭을 비슷한 경험과 함께 쓰세요.","answer_guide":{"answer":"예: 「비어 있는 의자만큼 / 보고 싶은 마음이 커져요」에서 감동을 느꼈다. 나도 유치원 때 친한 친구가 다른 동네로 이사 가서 그 친구 자리를 볼 때마다 보고 싶었기 때문이다.","scoring_points":["감동을 느낀 부분을 골랐는가","그렇게 느낀 까닭을 썼는가","작품과 닮은 경험을 썼는가"]},"explanation":["부분","까닭","닮은 경험"],"asset":{"type":"passage","lines":["짝꿍이 전학 간 날","옆 의자가 텅 비었어요","지우개 빌려 달라고","쿡쿡 찌를 데가 없어요","비어 있는 의자만큼","보고 싶은 마음이 커져요"],"title":"빈 의자"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u3_L06_challenge#9','kor',3,1,'u3','L06','g3_1_kor_u3_L06_challenge','lesson_challenge','K3-1-u3-C18',4,'essay','teacher','「아빠 수염」과 「빈 의자」를 낭송할 때 목소리를 어떻게 다르게 할지 쓰고, 그 까닭을 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K3-1-u3-C18","difficulty":4,"kind":"essay","stem":"「아빠 수염」과 「빈 의자」를 낭송할 때 목소리를 어떻게 다르게 할지 쓰고, 그 까닭을 쓰세요.","answer_guide":{"answer":"예: 「아빠 수염」은 밝고 장난스러운 목소리로, 「깔깔깔」은 웃음을 담아 읽는다. 「빈 의자」는 조금 느리고 차분하게 읽는다. 앞의 시는 웃음이 나는 재미가 있고, 뒤의 시는 짝을 그리워하는 마음이 담겨 있기 때문이다.","scoring_points":["「아빠 수염」의 목소리를 썼는가","「빈 의자」의 목소리를 썼는가","시의 마음을 까닭으로 들었는가"]},"explanation":["밝게","차분하게","시의 마음"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u3_L06_challenge#10','kor',3,1,'u3','L06','g3_1_kor_u3_L06_challenge','lesson_challenge','K3-1-u3-C20',4,'essay','teacher','친구가 「아빠 수염」을 읽고 「나는 하나도 재미없었어.」라고 했어요. 이 친구에게 해 줄 말을 쓰고, 그렇게 말한 까닭을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K3-1-u3-C20","difficulty":4,"kind":"essay","stem":"친구가 「아빠 수염」을 읽고 「나는 하나도 재미없었어.」라고 했어요. 이 친구에게 해 줄 말을 쓰고, 그렇게 말한 까닭을 쓰세요.","answer_guide":{"answer":"예: 「그렇게 느낄 수도 있지. 어느 부분에서 그렇게 느꼈는지 말해 줄래? 나는 면도기가 샘낸다는 말이 웃겼어.」 사람마다 느낌이 다를 수 있으니 서로 까닭을 들어 보면 작품을 더 넓게 볼 수 있기 때문이다.","scoring_points":["친구의 느낌을 받아 주었는가","친구의 까닭을 묻거나 내 느낌을 까닭과 함께 말했는가","감상이 저마다 다를 수 있음을 썼는가"]},"explanation":["받아 주기","까닭 나누기","저마다"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u3_L08_basic#1','kor',3,1,'u3','L08','g3_1_kor_u3_L08_basic','lesson_basic','K3-1-u3-C21',1,'mc','auto','「삐뚤빼뚤 연필꽂이」에서 연필꽂이를 만든 사람은 누구일까요?',ARRAY['K3-1-u3-X20']::text[],false,'{"seq":1,"concept":"K3-1-u3-C21","difficulty":1,"kind":"mc","stem":"「삐뚤빼뚤 연필꽂이」에서 연필꽂이를 만든 사람은 누구일까요?","options":[{"t":"동생 다은이","correct":true},{"t":"지후","mis":"K3-1-u3-X20"},{"t":"지후의 친구","mis":"K3-1-u3-X20"},{"t":"문구점 아저씨","mis":"K3-1-u3-X20"}],"explanation":["동생","다은이가","만들었어요"],"asset":{"type":"passage","lines":["지후는 생일날 동생 다은이에게 연필꽂이를 선물로 받았습니다.","종이 상자로 만든 연필꽂이는 삐뚤빼뚤했습니다.","여기저기 풀 자국도 묻어 있었습니다.","「에이, 이게 뭐야.」 지후는 연필꽂이를 책상 구석으로 밀어 두었습니다.","다음 날 아침, 지후는 다은이 방 앞에서 구겨진 종이 세 장을 보았습니다.","종이마다 「오빠 생일 선물 만들기」라고 적혀 있었습니다.","지후는 연필꽂이를 책상 한가운데로 옮기고 연필을 하나씩 꽂았습니다.","「다은아, 고마워. 오늘부터 이걸로 쓸게.」"],"title":"삐뚤빼뚤 연필꽂이"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u3_L08_basic#2','kor',3,1,'u3','L08','g3_1_kor_u3_L08_basic','lesson_basic','K3-1-u3-C22',1,'mc','auto','「삐뚤빼뚤 연필꽂이」에서 가장 먼저 일어난 일은 무엇일까요?',ARRAY['K3-1-u3-X21']::text[],false,'{"seq":2,"concept":"K3-1-u3-C22","difficulty":1,"kind":"mc","stem":"「삐뚤빼뚤 연필꽂이」에서 가장 먼저 일어난 일은 무엇일까요?","options":[{"t":"지후가 생일날 연필꽂이를 선물로 받았다.","correct":true},{"t":"지후가 연필을 하나씩 꽂았다.","mis":"K3-1-u3-X21"},{"t":"지후가 구겨진 종이를 보았다.","mis":"K3-1-u3-X21"},{"t":"지후가 다은이에게 고맙다고 했다.","mis":"K3-1-u3-X21"}],"explanation":["처음","생일 선물","받기"],"asset":{"type":"passage","lines":["지후는 생일날 동생 다은이에게 연필꽂이를 선물로 받았습니다.","종이 상자로 만든 연필꽂이는 삐뚤빼뚤했습니다.","여기저기 풀 자국도 묻어 있었습니다.","「에이, 이게 뭐야.」 지후는 연필꽂이를 책상 구석으로 밀어 두었습니다.","다음 날 아침, 지후는 다은이 방 앞에서 구겨진 종이 세 장을 보았습니다.","종이마다 「오빠 생일 선물 만들기」라고 적혀 있었습니다.","지후는 연필꽂이를 책상 한가운데로 옮기고 연필을 하나씩 꽂았습니다.","「다은아, 고마워. 오늘부터 이걸로 쓸게.」"],"title":"삐뚤빼뚤 연필꽂이"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u3_L08_basic#3','kor',3,1,'u3','L08','g3_1_kor_u3_L08_basic','lesson_basic','K3-1-u3-C27',1,'mc','auto','이야기에서 느낀 재미나 감동을 표현하는 방법으로 알맞지 않은 것은 무엇일까요?',ARRAY['K3-1-u3-X24']::text[],false,'{"seq":3,"concept":"K3-1-u3-C27","difficulty":1,"kind":"mc","stem":"이야기에서 느낀 재미나 감동을 표현하는 방법으로 알맞지 않은 것은 무엇일까요?","options":[{"t":"친구 작품을 그대로 베끼기","correct":true},{"t":"역할극으로 표현하기","mis":"K3-1-u3-X24"},{"t":"네 칸 만화로 그리기","mis":"K3-1-u3-X24"},{"t":"인물에게 편지 쓰기","mis":"K3-1-u3-X24"}],"explanation":["몸 · 그림 · 글","내 느낌으로","베끼기 ✗"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u3_L08_basic#4','kor',3,1,'u3','L08','g3_1_kor_u3_L08_basic','lesson_basic','K3-1-u3-C23',1,'mc','auto','모르는 낱말의 뜻을 짐작하는 좋은 방법은 무엇일까요?',ARRAY['K3-1-u3-X22']::text[],false,'{"seq":4,"concept":"K3-1-u3-C23","difficulty":1,"kind":"mc","stem":"모르는 낱말의 뜻을 짐작하는 좋은 방법은 무엇일까요?","options":[{"t":"앞뒤 문장을 읽고 어떤 상황인지 살핀다.","correct":true},{"t":"낱말의 소리만 듣고 정한다.","mis":"K3-1-u3-X22"},{"t":"모르는 낱말은 건너뛴다.","mis":"K3-1-u3-X22"},{"t":"비슷한 글자가 있는 낱말과 뜻이 같다고 여긴다.","mis":"K3-1-u3-X22"}],"explanation":["앞뒤 문장","상황","짐작"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u3_L08_basic#5','kor',3,1,'u3','L08','g3_1_kor_u3_L08_basic','lesson_basic','K3-1-u3-C23',2,'mc','auto','「연필꽂이를 책상 구석으로 밀어 두었습니다」에서 「구석」의 뜻으로 알맞은 것은 무엇일까요?',ARRAY['K3-1-u3-X22']::text[],false,'{"seq":5,"concept":"K3-1-u3-C23","difficulty":2,"kind":"mc","stem":"「연필꽂이를 책상 구석으로 밀어 두었습니다」에서 「구석」의 뜻으로 알맞은 것은 무엇일까요?","options":[{"t":"한쪽 끝의 잘 보이지 않는 자리","correct":true},{"t":"가장 잘 보이는 가운데 자리","mis":"K3-1-u3-X22"},{"t":"책상 서랍 속","mis":"K3-1-u3-X22"},{"t":"쓰레기통 안","mis":"K3-1-u3-X22"}],"explanation":["밀어 두었다","잘 안 보이는","구석"],"asset":{"type":"passage","lines":["지후는 생일날 동생 다은이에게 연필꽂이를 선물로 받았습니다.","종이 상자로 만든 연필꽂이는 삐뚤빼뚤했습니다.","여기저기 풀 자국도 묻어 있었습니다.","「에이, 이게 뭐야.」 지후는 연필꽂이를 책상 구석으로 밀어 두었습니다.","다음 날 아침, 지후는 다은이 방 앞에서 구겨진 종이 세 장을 보았습니다.","종이마다 「오빠 생일 선물 만들기」라고 적혀 있었습니다.","지후는 연필꽂이를 책상 한가운데로 옮기고 연필을 하나씩 꽂았습니다.","「다은아, 고마워. 오늘부터 이걸로 쓸게.」"],"title":"삐뚤빼뚤 연필꽂이"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u3_L08_basic#6','kor',3,1,'u3','L08','g3_1_kor_u3_L08_basic','lesson_basic','K3-1-u3-C23',2,'match','auto','낱말과 뜻을 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"K3-1-u3-C23","difficulty":2,"kind":"match","stem":"낱말과 뜻을 알맞게 이으세요.","pairs":[{"l":"삐뚤빼뚤","r":"곧지 못하고 이리저리 구부러진 모양"},{"l":"정성","r":"온 힘과 마음을 다하는 참된 마음"},{"l":"한가운데","r":"바로 가운데"}],"mis":"K3-1-u3-X22","explanation":["삐뚤빼뚤","정성","한가운데"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u3_L08_basic#7','kor',3,1,'u3','L08','g3_1_kor_u3_L08_basic','lesson_basic','K3-1-u3-C24',2,'mc','auto','재미나 감동을 한 문단으로 쓸 때 중심 문장에 들어갈 것은 무엇일까요?',ARRAY['K3-1-u3-X23','K3-1-u3-X16']::text[],false,'{"seq":7,"concept":"K3-1-u3-C24","difficulty":2,"kind":"mc","stem":"재미나 감동을 한 문단으로 쓸 때 중심 문장에 들어갈 것은 무엇일까요?","options":[{"t":"재미나 감동을 느낀 부분","correct":true},{"t":"그렇게 느낀 까닭만","mis":"K3-1-u3-X23"},{"t":"작품과 관계없는 내 이야기","mis":"K3-1-u3-X16"},{"t":"작품의 글자 수","mis":"K3-1-u3-X23"}],"explanation":["느낀 부분","중심 문장","까닭은 뒷받침"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u3_L08_basic#8','kor',3,1,'u3','L08','g3_1_kor_u3_L08_basic','lesson_basic','K3-1-u3-C26',2,'mc','auto','역할극으로 표현한다는 것은 무엇일까요?',ARRAY['K3-1-u3-X25','K3-1-u3-X24']::text[],false,'{"seq":8,"concept":"K3-1-u3-C26","difficulty":2,"kind":"mc","stem":"역할극으로 표현한다는 것은 무엇일까요?","options":[{"t":"인물이 되어 말과 몸짓으로 장면을 나타내는 것","correct":true},{"t":"장면을 네 칸에 그림으로 그리는 것","mis":"K3-1-u3-X25"},{"t":"인물에게 마음을 글로 전하는 것","mis":"K3-1-u3-X25"},{"t":"작품을 소리 없이 눈으로만 읽는 것","mis":"K3-1-u3-X24"}],"explanation":["인물이 되어","말과 몸짓","역할극"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u3_L08_basic#9','kor',3,1,'u3','L08','g3_1_kor_u3_L08_basic','lesson_basic','K3-1-u3-C21',2,'mc','auto','지후가 연필꽂이를 책상 한가운데로 옮긴 까닭은 무엇일까요?',ARRAY['K3-1-u3-X20']::text[],false,'{"seq":9,"concept":"K3-1-u3-C21","difficulty":2,"kind":"mc","stem":"지후가 연필꽂이를 책상 한가운데로 옮긴 까닭은 무엇일까요?","options":[{"t":"다은이가 여러 번 다시 만들며 마음을 쏟은 것을 알게 되어서","correct":true},{"t":"연필꽂이가 새것처럼 반듯해져서","mis":"K3-1-u3-X20"},{"t":"엄마가 옮기라고 해서","mis":"K3-1-u3-X20"},{"t":"구석에 자리가 없어서","mis":"K3-1-u3-X20"}],"explanation":["구겨진 종이 세 장","다은이의 마음","옮겼어요"],"asset":{"type":"passage","lines":["지후는 생일날 동생 다은이에게 연필꽂이를 선물로 받았습니다.","종이 상자로 만든 연필꽂이는 삐뚤빼뚤했습니다.","여기저기 풀 자국도 묻어 있었습니다.","「에이, 이게 뭐야.」 지후는 연필꽂이를 책상 구석으로 밀어 두었습니다.","다음 날 아침, 지후는 다은이 방 앞에서 구겨진 종이 세 장을 보았습니다.","종이마다 「오빠 생일 선물 만들기」라고 적혀 있었습니다.","지후는 연필꽂이를 책상 한가운데로 옮기고 연필을 하나씩 꽂았습니다.","「다은아, 고마워. 오늘부터 이걸로 쓸게.」"],"title":"삐뚤빼뚤 연필꽂이"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u3_L08_basic#10','kor',3,1,'u3','L08','g3_1_kor_u3_L08_basic','lesson_basic','K3-1-u3-C22',3,'mc','auto','「삐뚤빼뚤 연필꽂이」의 일을 차례대로 바르게 늘어놓은 것은 무엇일까요?',ARRAY['K3-1-u3-X21']::text[],false,'{"seq":10,"concept":"K3-1-u3-C22","difficulty":3,"kind":"mc","stem":"「삐뚤빼뚤 연필꽂이」의 일을 차례대로 바르게 늘어놓은 것은 무엇일까요?","options":[{"t":"선물을 받음 → 구석에 밀어 둠 → 구겨진 종이를 봄 → 한가운데로 옮김","correct":true},{"t":"구겨진 종이를 봄 → 선물을 받음 → 구석에 밀어 둠 → 한가운데로 옮김","mis":"K3-1-u3-X21"},{"t":"선물을 받음 → 한가운데로 옮김 → 구겨진 종이를 봄 → 구석에 밀어 둠","mis":"K3-1-u3-X21"},{"t":"한가운데로 옮김 → 선물을 받음 → 구석에 밀어 둠 → 구겨진 종이를 봄","mis":"K3-1-u3-X21"}],"explanation":["처음","가운데","끝"],"asset":{"type":"passage","lines":["지후는 생일날 동생 다은이에게 연필꽂이를 선물로 받았습니다.","종이 상자로 만든 연필꽂이는 삐뚤빼뚤했습니다.","여기저기 풀 자국도 묻어 있었습니다.","「에이, 이게 뭐야.」 지후는 연필꽂이를 책상 구석으로 밀어 두었습니다.","다음 날 아침, 지후는 다은이 방 앞에서 구겨진 종이 세 장을 보았습니다.","종이마다 「오빠 생일 선물 만들기」라고 적혀 있었습니다.","지후는 연필꽂이를 책상 한가운데로 옮기고 연필을 하나씩 꽂았습니다.","「다은아, 고마워. 오늘부터 이걸로 쓸게.」"],"title":"삐뚤빼뚤 연필꽂이"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u3_L08_challenge#1','kor',3,1,'u3','L08','g3_1_kor_u3_L08_challenge','lesson_challenge','K3-1-u3-C24',2,'mc','auto','감상 문단에서 「왜냐하면 ~ 때문이다」 부분은 어떤 문장이 될까요?',ARRAY['K3-1-u3-X23','K3-1-u3-X09']::text[],false,'{"seq":1,"concept":"K3-1-u3-C24","difficulty":2,"kind":"mc","stem":"감상 문단에서 「왜냐하면 ~ 때문이다」 부분은 어떤 문장이 될까요?","options":[{"t":"느낀 까닭을 말하는 뒷받침 문장","correct":true},{"t":"문단을 대표하는 중심 문장","mis":"K3-1-u3-X23"},{"t":"작품과 관계없는 문장","mis":"K3-1-u3-X09"},{"t":"작품의 제목","mis":"K3-1-u3-X23"}],"explanation":["왜냐하면","까닭","뒷받침"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u3_L08_challenge#2','kor',3,1,'u3','L08','g3_1_kor_u3_L08_challenge','lesson_challenge','K3-1-u3-C26',2,'mc','auto','네 칸 만화로 표현할 때의 특징은 무엇일까요?',ARRAY['K3-1-u3-X25','K3-1-u3-X24']::text[],false,'{"seq":2,"concept":"K3-1-u3-C26","difficulty":2,"kind":"mc","stem":"네 칸 만화로 표현할 때의 특징은 무엇일까요?","options":[{"t":"중요한 장면을 차례대로 그림으로 나타낸다.","correct":true},{"t":"인물이 되어 몸짓으로 연기한다.","mis":"K3-1-u3-X25"},{"t":"인물에게 편지로 마음을 전한다.","mis":"K3-1-u3-X25"},{"t":"그림 없이 글로만 쓴다.","mis":"K3-1-u3-X24"}],"explanation":["장면","차례대로","그림"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u3_L08_challenge#3','kor',3,1,'u3','L08','g3_1_kor_u3_L08_challenge','lesson_challenge','K3-1-u3-C24',3,'mc','auto','재미나 감동을 한 문단으로 바르게 쓴 것은 무엇일까요?',ARRAY['K3-1-u3-X23','K3-1-u3-X09']::text[],false,'{"seq":3,"concept":"K3-1-u3-C24","difficulty":3,"kind":"mc","stem":"재미나 감동을 한 문단으로 바르게 쓴 것은 무엇일까요?","options":[{"t":"나는 지후가 연필을 하나씩 꽂는 장면에서 감동을 느꼈다. 왜냐하면 동생의 마음을 알아주는 오빠가 따뜻했기 때문이다.","correct":true},{"t":"나는 이 이야기가 좋았다.","mis":"K3-1-u3-X23"},{"t":"왜냐하면 따뜻했기 때문이다. 나는 마지막 장면에서 감동을 느꼈다.","mis":"K3-1-u3-X23"},{"t":"나는 마지막 장면에서 감동을 느꼈다. 우리 집 연필은 파란색이다.","mis":"K3-1-u3-X09"}],"explanation":["느낀 부분","왜냐하면","까닭"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u3_L08_challenge#4','kor',3,1,'u3','L08','g3_1_kor_u3_L08_challenge','lesson_challenge','K3-1-u3-C21',3,'mc','auto','지후의 마음이 바뀌게 된 일은 무엇일까요?',ARRAY['K3-1-u3-X20','K3-1-u3-X21']::text[],false,'{"seq":4,"concept":"K3-1-u3-C21","difficulty":3,"kind":"mc","stem":"지후의 마음이 바뀌게 된 일은 무엇일까요?","options":[{"t":"구겨진 종이마다 「오빠 생일 선물 만들기」라고 적힌 것을 본 일","correct":true},{"t":"연필꽂이에 풀 자국이 묻어 있던 일","mis":"K3-1-u3-X20"},{"t":"생일날 선물을 받은 일","mis":"K3-1-u3-X21"},{"t":"「에이, 이게 뭐야.」라고 말한 일","mis":"K3-1-u3-X21"}],"explanation":["구겨진 종이","다은이의 노력","마음이 바뀜"],"asset":{"type":"passage","lines":["지후는 생일날 동생 다은이에게 연필꽂이를 선물로 받았습니다.","종이 상자로 만든 연필꽂이는 삐뚤빼뚤했습니다.","여기저기 풀 자국도 묻어 있었습니다.","「에이, 이게 뭐야.」 지후는 연필꽂이를 책상 구석으로 밀어 두었습니다.","다음 날 아침, 지후는 다은이 방 앞에서 구겨진 종이 세 장을 보았습니다.","종이마다 「오빠 생일 선물 만들기」라고 적혀 있었습니다.","지후는 연필꽂이를 책상 한가운데로 옮기고 연필을 하나씩 꽂았습니다.","「다은아, 고마워. 오늘부터 이걸로 쓸게.」"],"title":"삐뚤빼뚤 연필꽂이"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u3_L08_challenge#5','kor',3,1,'u3','L08','g3_1_kor_u3_L08_challenge','lesson_challenge','K3-1-u3-C21',3,'mc','auto','「구겨진 종이 세 장」으로 짐작할 수 있는 것은 무엇일까요?',ARRAY['K3-1-u3-X20','K3-1-u3-X22']::text[],false,'{"seq":5,"concept":"K3-1-u3-C21","difficulty":3,"kind":"mc","stem":"「구겨진 종이 세 장」으로 짐작할 수 있는 것은 무엇일까요?","options":[{"t":"다은이가 연필꽂이를 여러 번 다시 만들어 보았다.","correct":true},{"t":"다은이가 한 번 만에 쉽게 만들었다.","mis":"K3-1-u3-X20"},{"t":"다은이가 가게에서 연필꽂이를 샀다.","mis":"K3-1-u3-X20"},{"t":"알 수 없다 — 앞뒤 내용은 볼 필요가 없다.","mis":"K3-1-u3-X22"}],"explanation":["세 장","여러 번","노력"],"asset":{"type":"passage","lines":["지후는 생일날 동생 다은이에게 연필꽂이를 선물로 받았습니다.","종이 상자로 만든 연필꽂이는 삐뚤빼뚤했습니다.","여기저기 풀 자국도 묻어 있었습니다.","「에이, 이게 뭐야.」 지후는 연필꽂이를 책상 구석으로 밀어 두었습니다.","다음 날 아침, 지후는 다은이 방 앞에서 구겨진 종이 세 장을 보았습니다.","종이마다 「오빠 생일 선물 만들기」라고 적혀 있었습니다.","지후는 연필꽂이를 책상 한가운데로 옮기고 연필을 하나씩 꽂았습니다.","「다은아, 고마워. 오늘부터 이걸로 쓸게.」"],"title":"삐뚤빼뚤 연필꽂이"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u3_L08_challenge#6','kor',3,1,'u3','L08','g3_1_kor_u3_L08_challenge','lesson_challenge','K3-1-u3-C25',3,'mc','auto','「삐뚤빼뚤 연필꽂이」의 감동을 다은이에게 직접 전하고 싶을 때 가장 어울리는 표현 방법은 무엇일까요?',ARRAY['K3-1-u3-X26','K3-1-u3-X24','K3-1-u3-X28']::text[],false,'{"seq":6,"concept":"K3-1-u3-C25","difficulty":3,"kind":"mc","stem":"「삐뚤빼뚤 연필꽂이」의 감동을 다은이에게 직접 전하고 싶을 때 가장 어울리는 표현 방법은 무엇일까요?","options":[{"t":"다은이에게 편지 쓰기","correct":true},{"t":"친구가 그린 만화를 그대로 베끼기","mis":"K3-1-u3-X26"},{"t":"아무것도 하지 않기","mis":"K3-1-u3-X24"},{"t":"작품 제목만 크게 쓰기","mis":"K3-1-u3-X28"}],"explanation":["인물에게","마음을 글로","편지"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u3_L08_challenge#7','kor',3,1,'u3','L08','g3_1_kor_u3_L08_challenge','lesson_challenge','K3-1-u3-C27',3,'mc','auto','친구의 네 칸 만화가 멋져서 그대로 따라 그리려는 친구에게 해 줄 말로 알맞은 것은 무엇일까요?',ARRAY['K3-1-u3-X26','K3-1-u3-X24','K3-1-u3-X19']::text[],false,'{"seq":7,"concept":"K3-1-u3-C27","difficulty":3,"kind":"mc","stem":"친구의 네 칸 만화가 멋져서 그대로 따라 그리려는 친구에게 해 줄 말로 알맞은 것은 무엇일까요?","options":[{"t":"「네 마음에 남은 장면을 네 느낌대로 그려 봐.」","correct":true},{"t":"「그대로 베끼면 빨리 끝나서 좋아.」","mis":"K3-1-u3-X26"},{"t":"「만화는 잘 그리는 사람만 하는 거야.」","mis":"K3-1-u3-X24"},{"t":"「느낌은 하나만 맞으니 똑같이 그려야 해.」","mis":"K3-1-u3-X19"}],"explanation":["내 장면","내 느낌","나만의 표현"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u3_L08_challenge#8','kor',3,1,'u3','L08','g3_1_kor_u3_L08_challenge','lesson_challenge','K3-1-u3-C24',4,'essay','teacher','「삐뚤빼뚤 연필꽂이」에서 재미나 감동을 느낀 부분을 중심 문장으로, 그 까닭을 뒷받침 문장으로 하여 한 문단을 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K3-1-u3-C24","difficulty":4,"kind":"essay","stem":"「삐뚤빼뚤 연필꽂이」에서 재미나 감동을 느낀 부분을 중심 문장으로, 그 까닭을 뒷받침 문장으로 하여 한 문단을 쓰세요.","answer_guide":{"answer":"예: 나는 지후가 구겨진 종이를 보고 연필꽂이를 한가운데로 옮기는 장면에서 감동을 느꼈다. 왜냐하면 삐뚤빼뚤해도 동생이 여러 번 다시 만든 마음을 알아주었기 때문이다. 나도 선물에 담긴 마음을 먼저 생각해야겠다.","scoring_points":["느낀 부분을 중심 문장으로 썼는가","까닭을 뒷받침 문장으로 썼는가","「왜냐하면」 등으로 자연스럽게 이었는가"]},"explanation":["중심 문장","뒷받침 문장","한 문단"],"asset":{"type":"passage","lines":["지후는 생일날 동생 다은이에게 연필꽂이를 선물로 받았습니다.","종이 상자로 만든 연필꽂이는 삐뚤빼뚤했습니다.","여기저기 풀 자국도 묻어 있었습니다.","「에이, 이게 뭐야.」 지후는 연필꽂이를 책상 구석으로 밀어 두었습니다.","다음 날 아침, 지후는 다은이 방 앞에서 구겨진 종이 세 장을 보았습니다.","종이마다 「오빠 생일 선물 만들기」라고 적혀 있었습니다.","지후는 연필꽂이를 책상 한가운데로 옮기고 연필을 하나씩 꽂았습니다.","「다은아, 고마워. 오늘부터 이걸로 쓸게.」"],"title":"삐뚤빼뚤 연필꽂이"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u3_L08_challenge#9','kor',3,1,'u3','L08','g3_1_kor_u3_L08_challenge','lesson_challenge','K3-1-u3-C22',4,'essay','teacher','「삐뚤빼뚤 연필꽂이」의 일을 처음 · 가운데 · 끝으로 나누어 한 문장씩 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K3-1-u3-C22","difficulty":4,"kind":"essay","stem":"「삐뚤빼뚤 연필꽂이」의 일을 처음 · 가운데 · 끝으로 나누어 한 문장씩 쓰세요.","answer_guide":{"answer":"예: 처음 — 지후는 동생 다은이에게 삐뚤빼뚤한 연필꽂이를 받고 구석으로 밀어 두었다. 가운데 — 다음 날 아침 다은이 방 앞에서 「오빠 생일 선물 만들기」라고 적힌 구겨진 종이를 보았다. 끝 — 지후는 연필꽂이를 한가운데로 옮기고 다은이에게 고맙다고 했다.","scoring_points":["처음 일을 썼는가","가운데 일을 썼는가","끝 일을 차례에 맞게 썼는가"]},"explanation":["처음","가운데","끝"],"asset":{"type":"passage","lines":["지후는 생일날 동생 다은이에게 연필꽂이를 선물로 받았습니다.","종이 상자로 만든 연필꽂이는 삐뚤빼뚤했습니다.","여기저기 풀 자국도 묻어 있었습니다.","「에이, 이게 뭐야.」 지후는 연필꽂이를 책상 구석으로 밀어 두었습니다.","다음 날 아침, 지후는 다은이 방 앞에서 구겨진 종이 세 장을 보았습니다.","종이마다 「오빠 생일 선물 만들기」라고 적혀 있었습니다.","지후는 연필꽂이를 책상 한가운데로 옮기고 연필을 하나씩 꽂았습니다.","「다은아, 고마워. 오늘부터 이걸로 쓸게.」"],"title":"삐뚤빼뚤 연필꽂이"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u3_L08_challenge#10','kor',3,1,'u3','L08','g3_1_kor_u3_L08_challenge','lesson_challenge','K3-1-u3-C26',4,'essay','teacher','「삐뚤빼뚤 연필꽂이」의 한 장면을 역할극으로 표현한다면 어느 장면을 고를지 쓰고, 인물의 말과 몸짓을 어떻게 할지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K3-1-u3-C26","difficulty":4,"kind":"essay","stem":"「삐뚤빼뚤 연필꽂이」의 한 장면을 역할극으로 표현한다면 어느 장면을 고를지 쓰고, 인물의 말과 몸짓을 어떻게 할지 쓰세요.","answer_guide":{"answer":"예: 마지막 장면을 고르겠다. 지후는 연필꽂이를 두 손으로 조심스럽게 들어 책상 한가운데에 놓고, 다은이를 보며 쑥스럽게 웃으며 「다은아, 고마워.」라고 말한다.","scoring_points":["장면을 골랐는가","인물의 말을 썼는가","장면에 어울리는 몸짓을 썼는가"]},"explanation":["장면","말","몸짓"],"asset":{"type":"passage","lines":["지후는 생일날 동생 다은이에게 연필꽂이를 선물로 받았습니다.","종이 상자로 만든 연필꽂이는 삐뚤빼뚤했습니다.","여기저기 풀 자국도 묻어 있었습니다.","「에이, 이게 뭐야.」 지후는 연필꽂이를 책상 구석으로 밀어 두었습니다.","다음 날 아침, 지후는 다은이 방 앞에서 구겨진 종이 세 장을 보았습니다.","종이마다 「오빠 생일 선물 만들기」라고 적혀 있었습니다.","지후는 연필꽂이를 책상 한가운데로 옮기고 연필을 하나씩 꽂았습니다.","「다은아, 고마워. 오늘부터 이걸로 쓸게.」"],"title":"삐뚤빼뚤 연필꽂이"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u3_L11_basic#1','kor',3,1,'u3','L11','g3_1_kor_u3_L11_basic','lesson_basic','K3-1-u3-C28',1,'mc','auto','「나」 설명서는 어떤 글일까요?',ARRAY['K3-1-u3-X27','K3-1-u3-X01']::text[],false,'{"seq":1,"concept":"K3-1-u3-C28","difficulty":1,"kind":"mc","stem":"「나」 설명서는 어떤 글일까요?","options":[{"t":"나를 소개하는 내용을 중심 문장과 뒷받침 문장으로 짜임새 있게 쓴 글","correct":true},{"t":"친구의 비밀을 모아 쓴 글","mis":"K3-1-u3-X27"},{"t":"생각나는 대로 마구 늘어놓은 글","mis":"K3-1-u3-X01"},{"t":"나와 관계없는 소식을 모은 글","mis":"K3-1-u3-X27"}],"explanation":["나를 소개","중심 + 뒷받침","짜임새"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u3_L11_basic#2','kor',3,1,'u3','L11','g3_1_kor_u3_L11_basic','lesson_basic','K3-1-u3-C33',1,'mc','auto','「짜장면」과 「자장면」에 대해 바르게 말한 것은 무엇일까요?',ARRAY['K3-1-u3-X31']::text[],false,'{"seq":2,"concept":"K3-1-u3-C33","difficulty":1,"kind":"mc","stem":"「짜장면」과 「자장면」에 대해 바르게 말한 것은 무엇일까요?","options":[{"t":"둘 다 표준어예요.","correct":true},{"t":"「자장면」만 표준어예요.","mis":"K3-1-u3-X31"},{"t":"「짜장면」만 표준어예요.","mis":"K3-1-u3-X31"},{"t":"둘 다 표준어가 아니에요.","mis":"K3-1-u3-X31"}],"explanation":["뜻이 같은","두 말","둘 다 표준어"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
