INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u3_L11_challenge#6','kor',3,1,'u3','L11','g3_1_kor_u3_L11_challenge','lesson_challenge','K3-1-u3-C28',3,'mc','auto','「나」 설명서를 더 짜임새 있게 고치는 방법으로 알맞은 것은 무엇일까요?',ARRAY['K3-1-u3-X03','K3-1-u3-X27','K3-1-u3-X11']::text[],false,'{"seq":6,"concept":"K3-1-u3-C28","difficulty":3,"kind":"mc","stem":"「나」 설명서를 더 짜임새 있게 고치는 방법으로 알맞은 것은 무엇일까요?","options":[{"t":"좋아하는 것 하나를 중심 문장으로 정하고 그와 어울리는 문장만 이어 쓴다.","correct":true},{"t":"나와 관계된 것이면 무엇이든 한 문단에 모두 넣는다.","mis":"K3-1-u3-X03"},{"t":"친구의 재미있는 비밀을 넣어 눈길을 끈다.","mis":"K3-1-u3-X27"},{"t":"중심 문장 하나만 크게 쓴다.","mis":"K3-1-u3-X11"}],"explanation":["한 가지 생각","어울리는 문장","짜임새"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u3_L11_challenge#7','kor',3,1,'u3','L11','g3_1_kor_u3_L11_challenge','lesson_challenge','K3-1-u3-C30',3,'mc','auto','우리 동네를 소개하는 글을 쓸 때 배운 것을 살린 방법은 무엇일까요?',ARRAY['K3-1-u3-X01','K3-1-u3-X32','K3-1-u3-X02']::text[],false,'{"seq":7,"concept":"K3-1-u3-C30","difficulty":3,"kind":"mc","stem":"우리 동네를 소개하는 글을 쓸 때 배운 것을 살린 방법은 무엇일까요?","options":[{"t":"「우리 동네에는 쉴 곳이 많습니다.」를 중심 문장으로 두고 공원 · 쉼터를 예로 들어 뒷받침한다.","correct":true},{"t":"생각나는 대로 동네 이야기를 마구 쓴다.","mis":"K3-1-u3-X01"},{"t":"국어 시간이 아니니 짜임새는 생각하지 않는다.","mis":"K3-1-u3-X32"},{"t":"한 문장마다 새 문단으로 쓴다.","mis":"K3-1-u3-X02"}],"explanation":["중심 문장","예를 들어","생활 속 글"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u3_L11_challenge#8','kor',3,1,'u3','L11','g3_1_kor_u3_L11_challenge','lesson_challenge','K3-1-u3-C28',4,'essay','teacher','나를 소개하는 「나」 설명서를 중심 문장 하나와 뒷받침 문장 세 개로 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K3-1-u3-C28","difficulty":4,"kind":"essay","stem":"나를 소개하는 「나」 설명서를 중심 문장 하나와 뒷받침 문장 세 개로 쓰세요.","answer_guide":{"answer":"예: 나는 종이접기를 잘합니다. 색종이 한 장으로 학과 개구리를 접을 수 있습니다. 쉬는 시간에 친구들에게 접는 방법을 알려 줍니다. 요즘은 종이접기 책을 보며 공룡 접기를 연습합니다.","scoring_points":["나를 보여 주는 중심 문장을 썼는가","뒷받침 문장 세 개를 썼는가","뒷받침 문장이 모두 중심 문장과 어울리는가"]},"explanation":["중심 문장","뒷받침 셋","어울림"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u3_L11_challenge#9','kor',3,1,'u3','L11','g3_1_kor_u3_L11_challenge','lesson_challenge','K3-1-u3-C29',4,'essay','teacher','서아의 소개 자료에 빠진 것을 찾아 채워 쓰고, 그것이 꼭 필요한 까닭을 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K3-1-u3-C29","difficulty":4,"kind":"essay","stem":"서아의 소개 자료에 빠진 것을 찾아 채워 쓰고, 그것이 꼭 필요한 까닭을 쓰세요.","answer_guide":{"answer":"예: 빠진 것은 느낀 까닭이다. 「동생이 여러 번 다시 만든 마음을 오빠가 알아줘서 따뜻했기 때문이다.」라고 채운다. 까닭이 있어야 보는 사람이 왜 그렇게 느꼈는지 알 수 있다.","scoring_points":["빠진 것이 까닭임을 찾았는가","까닭을 채워 썼는가","까닭이 필요한 이유를 썼는가"]},"explanation":["까닭 찾기","채우기","필요한 이유"],"asset":{"type":"passage","lines":["작품 제목: 삐뚤빼뚤 연필꽂이","느낀 점: 지후가 연필을 하나씩 꽂는 장면에서 마음이 따뜻해졌다.","표현 방법: 다은이에게 보내는 편지"],"title":"서아의 소개 자료"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u3_L11_challenge#10','kor',3,1,'u3','L11','g3_1_kor_u3_L11_challenge','lesson_challenge','K3-1-u3-C31',4,'essay','teacher','「놓지」와 「백화점」의 바른 발음을 쓰고, 소리가 어떻게 바뀌었는지 설명하세요.','{}'::text[],false,'{"seq":10,"concept":"K3-1-u3-C31","difficulty":4,"kind":"essay","stem":"「놓지」와 「백화점」의 바른 발음을 쓰고, 소리가 어떻게 바뀌었는지 설명하세요.","answer_guide":{"answer":"예: 「놓지」는 [노치]로 읽는다. 받침 ㅎ 뒤에 ㅈ이 와서 [ㅊ]으로 소리 난다. 「백화점」은 [배콰점]으로 읽는다. 받침 ㄱ 뒤에 ㅎ이 와서 [ㅋ]으로 소리 난다.","scoring_points":["「놓지」의 발음을 바르게 썼는가","「백화점」의 발음을 바르게 썼는가","소리가 바뀐 까닭을 설명했는가"]},"explanation":["[노치]","[배콰점]","ㅎ이 만나면"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u3_review_a#1','kor',3,1,'u3','','g3_1_kor_u3_review_a','unit_review','K3-1-u3-C3',1,'mc','auto','여러 문장이 모여 한 가지 생각을 나타내는 글의 단위를 무엇이라고 할까요?',ARRAY['K3-1-u3-X06','K3-1-u3-X02']::text[],false,'{"seq":1,"concept":"K3-1-u3-C3","difficulty":1,"kind":"mc","stem":"여러 문장이 모여 한 가지 생각을 나타내는 글의 단위를 무엇이라고 할까요?","options":[{"t":"문단","correct":true},{"t":"중심 문장","mis":"K3-1-u3-X06"},{"t":"낱말","mis":"K3-1-u3-X02"},{"t":"제목","mis":"K3-1-u3-X02"}],"explanation":["문장이 모여","한 가지 생각","문단"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u3_review_a#2','kor',3,1,'u3','','g3_1_kor_u3_review_a','unit_review','K3-1-u3-C14',1,'mc','auto','「양말 한 짝」을 읽고 웃음이 났다면 무엇을 느낀 것일까요?',ARRAY['K3-1-u3-X14','K3-1-u3-X15']::text[],false,'{"seq":2,"concept":"K3-1-u3-C14","difficulty":1,"kind":"mc","stem":"「양말 한 짝」을 읽고 웃음이 났다면 무엇을 느낀 것일까요?","options":[{"t":"재미","correct":true},{"t":"슬픔","mis":"K3-1-u3-X14"},{"t":"지루함","mis":"K3-1-u3-X15"},{"t":"아무것도 느끼지 않음","mis":"K3-1-u3-X15"}],"explanation":["웃음","엉뚱한 생각","재미"],"asset":{"type":"passage","lines":["빨래 바구니에서","양말 한 짝이 사라졌다","소파 밑에도 없고","침대 밑에도 없다","혹시 너 혼자","여행 갔니?"],"title":"양말 한 짝"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u3_review_a#3','kor',3,1,'u3','','g3_1_kor_u3_review_a','unit_review','K3-1-u3-C22',1,'mc','auto','이야기의 일을 정리할 때 무엇에 따라 늘어놓을까요?',ARRAY['K3-1-u3-X21']::text[],false,'{"seq":3,"concept":"K3-1-u3-C22","difficulty":1,"kind":"mc","stem":"이야기의 일을 정리할 때 무엇에 따라 늘어놓을까요?","options":[{"t":"일어난 차례","correct":true},{"t":"마음에 드는 차례","mis":"K3-1-u3-X21"},{"t":"글자 수가 많은 차례","mis":"K3-1-u3-X21"},{"t":"가나다 차례","mis":"K3-1-u3-X21"}],"explanation":["처음","가운데","끝"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u3_review_a#4','kor',3,1,'u3','','g3_1_kor_u3_review_a','unit_review','K3-1-u3-C31',1,'mc','auto','「좋고」의 바른 발음은 무엇일까요?',ARRAY['K3-1-u3-X29','K3-1-u3-X30']::text[],false,'{"seq":4,"concept":"K3-1-u3-C31","difficulty":1,"kind":"mc","stem":"「좋고」의 바른 발음은 무엇일까요?","options":[{"t":"[조코]","correct":true},{"t":"[좋고]","mis":"K3-1-u3-X29"},{"t":"[조고]","mis":"K3-1-u3-X30"},{"t":"[졷꼬]","mis":"K3-1-u3-X30"}],"explanation":["받침 ㅎ","+ ㄱ","[ㅋ]"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u3_review_a#5','kor',3,1,'u3','','g3_1_kor_u3_review_a','unit_review','K3-1-u3-C9',1,'mc','auto','「비 오는 날에는 여러 가지 소리가 들립니다.」에 어울리는 뒷받침 문장은 무엇일까요?',ARRAY['K3-1-u3-X09','K3-1-u3-X08']::text[],false,'{"seq":5,"concept":"K3-1-u3-C9","difficulty":1,"kind":"mc","stem":"「비 오는 날에는 여러 가지 소리가 들립니다.」에 어울리는 뒷받침 문장은 무엇일까요?","options":[{"t":"우산 위로 빗소리가 후두둑 납니다.","correct":true},{"t":"나는 맑은 날을 좋아합니다.","mis":"K3-1-u3-X09"},{"t":"비 오는 날에는 소리가 많이 들립니다.","mis":"K3-1-u3-X08"},{"t":"우리 집 고양이는 세 살입니다.","mis":"K3-1-u3-X09"}],"explanation":["빗소리","예","어울림"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u3_review_a#6','kor',3,1,'u3','','g3_1_kor_u3_review_a','unit_review','K3-1-u3-C2',1,'mc','auto','짜임새 있는 글을 읽는 사람은 어떨까요?',ARRAY['K3-1-u3-X01','K3-1-u3-X08','K3-1-u3-X03']::text[],false,'{"seq":6,"concept":"K3-1-u3-C2","difficulty":1,"kind":"mc","stem":"짜임새 있는 글을 읽는 사람은 어떨까요?","options":[{"t":"내용을 쉽게 알 수 있어요.","correct":true},{"t":"무슨 뜻인지 알기 어려워요.","mis":"K3-1-u3-X01"},{"t":"같은 말만 계속 나와 지루해요.","mis":"K3-1-u3-X08"},{"t":"생각이 뒤죽박죽 섞여 헷갈려요.","mis":"K3-1-u3-X03"}],"explanation":["짜임새","쉽게","이해"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u3_review_a#7','kor',3,1,'u3','','g3_1_kor_u3_review_a','unit_review','K3-1-u3-C16',1,'mc','auto','시를 읽을 때 떠오르는 장면을 그려 보면 어떤 점이 좋을까요?',ARRAY['K3-1-u3-X17','K3-1-u3-X15','K3-1-u3-X16']::text[],false,'{"seq":7,"concept":"K3-1-u3-C16","difficulty":1,"kind":"mc","stem":"시를 읽을 때 떠오르는 장면을 그려 보면 어떤 점이 좋을까요?","options":[{"t":"시 속 일이 눈앞에 보이듯 생생하게 느껴져요.","correct":true},{"t":"글자를 빨리 읽을 수 있어요.","mis":"K3-1-u3-X17"},{"t":"아무 차이가 없어요.","mis":"K3-1-u3-X15"},{"t":"작품과 관계없는 일을 떠올릴 수 있어요.","mis":"K3-1-u3-X16"}],"explanation":["장면","눈앞에","생생하게"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u3_review_a#8','kor',3,1,'u3','','g3_1_kor_u3_review_a','unit_review','K3-1-u3-C23',1,'mc','auto','「물건을 아껴 쓰다」에서 「아끼다」의 뜻으로 알맞은 것은 무엇일까요?',ARRAY['K3-1-u3-X22']::text[],false,'{"seq":8,"concept":"K3-1-u3-C23","difficulty":1,"kind":"mc","stem":"「물건을 아껴 쓰다」에서 「아끼다」의 뜻으로 알맞은 것은 무엇일까요?","options":[{"t":"소중히 여겨 함부로 쓰지 않다","correct":true},{"t":"마구 써서 빨리 없애다","mis":"K3-1-u3-X22"},{"t":"남에게 모두 주다","mis":"K3-1-u3-X22"},{"t":"잃어버리다","mis":"K3-1-u3-X22"}],"explanation":["아껴 쓰다","소중히","함부로 ✗"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u3_review_a#9','kor',3,1,'u3','','g3_1_kor_u3_review_a','unit_review','K3-1-u3-C4',2,'mc','auto','「우리 동네 시장」에서 가장 중요한 생각을 담은 문장은 몇째 문장일까요?',ARRAY['K3-1-u3-X04','K3-1-u3-X06']::text[],false,'{"seq":9,"concept":"K3-1-u3-C4","difficulty":2,"kind":"mc","stem":"「우리 동네 시장」에서 가장 중요한 생각을 담은 문장은 몇째 문장일까요?","options":[{"t":"첫째 문장","correct":true},{"t":"넷째 문장 — 가장 길어서","mis":"K3-1-u3-X04"},{"t":"둘째 문장 — 붕어빵이 맛있어서","mis":"K3-1-u3-X06"},{"t":"셋째 문장 — 떡이 알록달록해서","mis":"K3-1-u3-X06"}],"explanation":["먹거리가 많다","모두 묶는","첫째"],"asset":{"type":"passage","lines":["우리 동네 시장에는 맛있는 먹거리가 많습니다.","시장 입구에서는 갓 구운 붕어빵을 팝니다.","떡집에는 알록달록한 떡이 줄지어 놓여 있습니다.","시장 끝 가게에서는 따끈한 어묵 국물 냄새가 납니다."],"title":"우리 동네 시장"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u3_review_a#10','kor',3,1,'u3','','g3_1_kor_u3_review_a','unit_review','K3-1-u3-C9',2,'mc','auto','「우리 동네 시장」에 넣기에 어울리지 않는 문장은 무엇일까요?',ARRAY['K3-1-u3-X09']::text[],false,'{"seq":10,"concept":"K3-1-u3-C9","difficulty":2,"kind":"mc","stem":"「우리 동네 시장」에 넣기에 어울리지 않는 문장은 무엇일까요?","options":[{"t":"시장 옆 학교에는 학생이 많습니다.","correct":true},{"t":"과일 가게에는 달콤한 귤이 쌓여 있습니다.","mis":"K3-1-u3-X09"},{"t":"김밥집에서는 김밥을 바로 말아 줍니다.","mis":"K3-1-u3-X09"},{"t":"호떡 가게 앞에는 줄이 깁니다.","mis":"K3-1-u3-X09"}],"explanation":["먹거리","학교는","관계없어요"],"asset":{"type":"passage","lines":["우리 동네 시장에는 맛있는 먹거리가 많습니다.","시장 입구에서는 갓 구운 붕어빵을 팝니다.","떡집에는 알록달록한 떡이 줄지어 놓여 있습니다.","시장 끝 가게에서는 따끈한 어묵 국물 냄새가 납니다."],"title":"우리 동네 시장"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u3_review_a#11','kor',3,1,'u3','','g3_1_kor_u3_review_a','unit_review','K3-1-u3-C14',2,'mc','auto','「양말 한 짝」에서 재미를 느낄 수 있는 부분은 어디일까요?',ARRAY['K3-1-u3-X15','K3-1-u3-X14']::text[],false,'{"seq":11,"concept":"K3-1-u3-C14","difficulty":2,"kind":"mc","stem":"「양말 한 짝」에서 재미를 느낄 수 있는 부분은 어디일까요?","options":[{"t":"「혹시 너 혼자 / 여행 갔니?」 — 양말이 여행을 갔다는 엉뚱한 생각","correct":true},{"t":"「빨래 바구니에서」 — 빨래가 많아서","mis":"K3-1-u3-X15"},{"t":"없어요 — 슬프지 않으니 느낄 것이 없어요","mis":"K3-1-u3-X14"},{"t":"제목 — 글자가 다섯 개라서","mis":"K3-1-u3-X15"}],"explanation":["엉뚱한","상상","재미"],"asset":{"type":"passage","lines":["빨래 바구니에서","양말 한 짝이 사라졌다","소파 밑에도 없고","침대 밑에도 없다","혹시 너 혼자","여행 갔니?"],"title":"양말 한 짝"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u3_review_a#12','kor',3,1,'u3','','g3_1_kor_u3_review_a','unit_review','K3-1-u3-C19',2,'mc','auto','다음 발표 가운데 까닭이 들어 있는 것은 무엇일까요?',ARRAY['K3-1-u3-X18','K3-1-u3-X26']::text[],false,'{"seq":12,"concept":"K3-1-u3-C19","difficulty":2,"kind":"mc","stem":"다음 발표 가운데 까닭이 들어 있는 것은 무엇일까요?","options":[{"t":"「빈 의자」가 뭉클했어요. 짝을 그리워하는 마음이 느껴졌거든요.","correct":true},{"t":"「빈 의자」가 좋았어요.","mis":"K3-1-u3-X18"},{"t":"「빈 의자」는 그냥 그랬어요.","mis":"K3-1-u3-X18"},{"t":"하윤이가 좋았다니 나도 좋았어요.","mis":"K3-1-u3-X26"}],"explanation":["느낌","거든요","까닭"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u3_review_a#13','kor',3,1,'u3','','g3_1_kor_u3_review_a','unit_review','K3-1-u3-C22',2,'mc','auto','「삐뚤빼뚤 연필꽂이」에서 지후가 구겨진 종이를 본 것은 언제일까요?',ARRAY['K3-1-u3-X21']::text[],false,'{"seq":13,"concept":"K3-1-u3-C22","difficulty":2,"kind":"mc","stem":"「삐뚤빼뚤 연필꽂이」에서 지후가 구겨진 종이를 본 것은 언제일까요?","options":[{"t":"연필꽂이를 구석에 밀어 둔 다음 날 아침","correct":true},{"t":"선물을 받기 전날","mis":"K3-1-u3-X21"},{"t":"연필을 꽂은 다음","mis":"K3-1-u3-X21"},{"t":"다은이에게 고맙다고 한 뒤","mis":"K3-1-u3-X21"}],"explanation":["밀어 둔 뒤","다음 날 아침","차례"],"asset":{"type":"passage","lines":["지후는 생일날 동생 다은이에게 연필꽂이를 선물로 받았습니다.","종이 상자로 만든 연필꽂이는 삐뚤빼뚤했습니다.","여기저기 풀 자국도 묻어 있었습니다.","「에이, 이게 뭐야.」 지후는 연필꽂이를 책상 구석으로 밀어 두었습니다.","다음 날 아침, 지후는 다은이 방 앞에서 구겨진 종이 세 장을 보았습니다.","종이마다 「오빠 생일 선물 만들기」라고 적혀 있었습니다.","지후는 연필꽂이를 책상 한가운데로 옮기고 연필을 하나씩 꽂았습니다.","「다은아, 고마워. 오늘부터 이걸로 쓸게.」"],"title":"삐뚤빼뚤 연필꽂이"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
