INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u3_review_a#15','kor',3,1,'u3','','g3_1_kor_u3_review_a','unit_review','K3-1-u3-C31',2,'mc','auto','「넣지」의 바른 발음은 무엇일까요?',ARRAY['K3-1-u3-X29','K3-1-u3-X30']::text[],false,'{"seq":15,"concept":"K3-1-u3-C31","difficulty":2,"kind":"mc","stem":"「넣지」의 바른 발음은 무엇일까요?","options":[{"t":"[너치]","correct":true},{"t":"[넣지]","mis":"K3-1-u3-X29"},{"t":"[너지]","mis":"K3-1-u3-X30"},{"t":"[넏찌]","mis":"K3-1-u3-X30"}],"explanation":["받침 ㅎ","+ ㅈ","[ㅊ]"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u3_review_a#16','kor',3,1,'u3','','g3_1_kor_u3_review_a','unit_review','K3-1-u3-C29',2,'mc','auto','작품 소개 자료를 친구들과 나누면 좋은 점은 무엇일까요?',ARRAY['K3-1-u3-X19','K3-1-u3-X26','K3-1-u3-X28']::text[],false,'{"seq":16,"concept":"K3-1-u3-C29","difficulty":2,"kind":"mc","stem":"작품 소개 자료를 친구들과 나누면 좋은 점은 무엇일까요?","options":[{"t":"같은 작품에서도 서로 다른 재미와 감동을 알게 돼요.","correct":true},{"t":"누구 느낌이 맞는지 가릴 수 있어요.","mis":"K3-1-u3-X19"},{"t":"친구 자료를 베낄 수 있어요.","mis":"K3-1-u3-X26"},{"t":"제목만 보면 돼요.","mis":"K3-1-u3-X28"}],"explanation":["나누기","서로 다른","느낌"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u3_review_a#17','kor',3,1,'u3','','g3_1_kor_u3_review_a','unit_review','K3-1-u3-C8',3,'mc','auto','「겨울을 나는 동물」처럼 중심 문장이 끝에 오면 어떤 점이 좋을까요?',ARRAY['K3-1-u3-X05','K3-1-u3-X11','K3-1-u3-X04']::text[],false,'{"seq":17,"concept":"K3-1-u3-C8","difficulty":3,"kind":"mc","stem":"「겨울을 나는 동물」처럼 중심 문장이 끝에 오면 어떤 점이 좋을까요?","options":[{"t":"예를 다 읽은 뒤 생각을 한데 모아 정리해 줘요.","correct":true},{"t":"중심 문장은 끝에 오면 안 돼요.","mis":"K3-1-u3-X05"},{"t":"끝에 오면 뒷받침 문장이 필요 없어요.","mis":"K3-1-u3-X11"},{"t":"가장 긴 문장이라서 좋아요.","mis":"K3-1-u3-X04"}],"explanation":["예 먼저","끝에서","모아 정리"],"asset":{"type":"passage","lines":["개구리는 땅속에 들어가 겨울을 납니다.","곰은 깊은 굴속에서 겨울을 보냅니다.","박쥐는 동굴 천장에 거꾸로 매달려 잠을 잡니다.","이렇게 추운 겨울 동안 잠을 자며 지내는 동물이 많습니다."],"title":"겨울을 나는 동물"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u3_review_a#18','kor',3,1,'u3','','g3_1_kor_u3_review_a','unit_review','K3-1-u3-C10',3,'mc','auto','「우리 집 베란다」의 마지막 문장을 바꾸려고 해요. 가장 알맞은 문장은 무엇일까요?',ARRAY['K3-1-u3-X10','K3-1-u3-X08']::text[],false,'{"seq":18,"concept":"K3-1-u3-C10","difficulty":3,"kind":"mc","stem":"「우리 집 베란다」의 마지막 문장을 바꾸려고 해요. 가장 알맞은 문장은 무엇일까요?","options":[{"t":"가지도 보랏빛 열매를 달았습니다.","correct":true},{"t":"나는 축구와 농구를 잘합니다.","mis":"K3-1-u3-X10"},{"t":"우리 집 베란다에서는 채소가 자랍니다.","mis":"K3-1-u3-X08"},{"t":"내일은 소풍을 갑니다.","mis":"K3-1-u3-X10"}],"explanation":["채소 이야기","바꾸기","어울림"],"asset":{"type":"passage","lines":["우리 집 베란다에서는 여러 가지 채소가 자랍니다.","상추가 넓은 잎을 펼칩니다.","방울토마토가 빨갛게 익어 갑니다.","고추는 하얀 꽃을 피웠습니다.","나는 축구를 잘합니다."],"title":"우리 집 베란다"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u3_review_a#19','kor',3,1,'u3','','g3_1_kor_u3_review_a','unit_review','K3-1-u3-C16',3,'mc','auto','「빈 의자」의 「쿡쿡 찌를 데가 없어요」를 읽고 떠올릴 장면으로 가장 알맞은 것은 무엇일까요?',ARRAY['K3-1-u3-X20','K3-1-u3-X15']::text[],false,'{"seq":19,"concept":"K3-1-u3-C16","difficulty":3,"kind":"mc","stem":"「빈 의자」의 「쿡쿡 찌를 데가 없어요」를 읽고 떠올릴 장면으로 가장 알맞은 것은 무엇일까요?","options":[{"t":"장난치던 짝이 없어 허전하게 옆자리를 보는 모습","correct":true},{"t":"친구를 아프게 찌르는 모습","mis":"K3-1-u3-X20"},{"t":"의자를 새로 고치는 모습","mis":"K3-1-u3-X15"},{"t":"짝과 다투는 모습","mis":"K3-1-u3-X15"}],"explanation":["쿡쿡","장난칠 짝이 없음","허전함"],"asset":{"type":"passage","lines":["짝꿍이 전학 간 날","옆 의자가 텅 비었어요","지우개 빌려 달라고","쿡쿡 찌를 데가 없어요","비어 있는 의자만큼","보고 싶은 마음이 커져요"],"title":"빈 의자"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u3_review_a#20','kor',3,1,'u3','','g3_1_kor_u3_review_a','unit_review','K3-1-u3-C22',3,'mc','auto','「삐뚤빼뚤 연필꽂이」의 끝부분에서 일어난 일은 무엇일까요?',ARRAY['K3-1-u3-X21']::text[],false,'{"seq":20,"concept":"K3-1-u3-C22","difficulty":3,"kind":"mc","stem":"「삐뚤빼뚤 연필꽂이」의 끝부분에서 일어난 일은 무엇일까요?","options":[{"t":"지후가 연필꽂이를 한가운데로 옮기고 다은이에게 고맙다고 했다.","correct":true},{"t":"지후가 연필꽂이를 구석으로 밀었다.","mis":"K3-1-u3-X21"},{"t":"다은이가 종이 상자를 구했다.","mis":"K3-1-u3-X21"},{"t":"지후가 생일 선물을 받았다.","mis":"K3-1-u3-X21"}],"explanation":["끝","한가운데","고마워"],"asset":{"type":"passage","lines":["지후는 생일날 동생 다은이에게 연필꽂이를 선물로 받았습니다.","종이 상자로 만든 연필꽂이는 삐뚤빼뚤했습니다.","여기저기 풀 자국도 묻어 있었습니다.","「에이, 이게 뭐야.」 지후는 연필꽂이를 책상 구석으로 밀어 두었습니다.","다음 날 아침, 지후는 다은이 방 앞에서 구겨진 종이 세 장을 보았습니다.","종이마다 「오빠 생일 선물 만들기」라고 적혀 있었습니다.","지후는 연필꽂이를 책상 한가운데로 옮기고 연필을 하나씩 꽂았습니다.","「다은아, 고마워. 오늘부터 이걸로 쓸게.」"],"title":"삐뚤빼뚤 연필꽂이"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u3_review_a#21','kor',3,1,'u3','','g3_1_kor_u3_review_a','unit_review','K3-1-u3-C28',3,'mc','auto','「나」 설명서를 읽은 친구가 「너에 대해 잘 알게 됐어.」라고 했어요. 이 글의 좋은 점으로 알맞은 것은 무엇일까요?',ARRAY['K3-1-u3-X27','K3-1-u3-X03','K3-1-u3-X11']::text[],false,'{"seq":21,"concept":"K3-1-u3-C28","difficulty":3,"kind":"mc","stem":"「나」 설명서를 읽은 친구가 「너에 대해 잘 알게 됐어.」라고 했어요. 이 글의 좋은 점으로 알맞은 것은 무엇일까요?","options":[{"t":"나를 보여 주는 한 가지 생각을 뒷받침 문장으로 자세히 썼다.","correct":true},{"t":"친구 비밀을 넣어 재미있게 썼다.","mis":"K3-1-u3-X27"},{"t":"생각나는 대로 여러 이야기를 섞었다.","mis":"K3-1-u3-X03"},{"t":"중심 문장 하나만 짧게 썼다.","mis":"K3-1-u3-X11"}],"explanation":["한 가지 생각","자세히","나를 보여 줌"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u3_review_a#22','kor',3,1,'u3','','g3_1_kor_u3_review_a','unit_review','K3-1-u3-C30',3,'mc','auto','영화를 보고 느낀 점을 글로 쓸 때 배운 것을 살린 방법은 무엇일까요?',ARRAY['K3-1-u3-X28','K3-1-u3-X03','K3-1-u3-X32']::text[],false,'{"seq":22,"concept":"K3-1-u3-C30","difficulty":3,"kind":"mc","stem":"영화를 보고 느낀 점을 글로 쓸 때 배운 것을 살린 방법은 무엇일까요?","options":[{"t":"느낀 장면을 중심 문장으로, 그 까닭을 뒷받침 문장으로 쓴다.","correct":true},{"t":"영화 제목만 크게 쓴다.","mis":"K3-1-u3-X28"},{"t":"영화와 관계없는 일을 섞어 쓴다.","mis":"K3-1-u3-X03"},{"t":"국어 숙제가 아니니 아무렇게나 쓴다.","mis":"K3-1-u3-X32"}],"explanation":["느낀 장면","까닭","생활 속"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u3_review_a#23','kor',3,1,'u3','','g3_1_kor_u3_review_a','unit_review','K3-1-u3-C4',4,'essay','teacher','「비 오는 날의 소리」의 중심 문장과 뒷받침 문장을 찾아 쓰고, 어떻게 구별했는지 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K3-1-u3-C4","difficulty":4,"kind":"essay","stem":"「비 오는 날의 소리」의 중심 문장과 뒷받침 문장을 찾아 쓰고, 어떻게 구별했는지 쓰세요.","answer_guide":{"answer":"예: 중심 문장은 「비 오는 날에는 여러 가지 소리가 들립니다.」이다. 뒷받침 문장은 창문 · 지붕 · 자동차 소리를 말한 나머지 세 문장이다. 나머지 문장들이 말하는 소리를 모두 묶어 주는 문장이 중심 문장이라서 그렇게 구별했다.","scoring_points":["중심 문장을 찾았는가","뒷받침 문장을 찾았는가","구별한 방법을 썼는가"]},"explanation":["중심","뒷받침","구별"],"asset":{"type":"passage","lines":["비 오는 날에는 여러 가지 소리가 들립니다.","창문에 빗방울이 톡톡 부딪칩니다.","지붕 위에서는 빗물이 똑똑 떨어집니다.","자동차가 지나가면 고인 물이 촤악 튑니다."],"title":"비 오는 날의 소리"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u3_review_a#24','kor',3,1,'u3','','g3_1_kor_u3_review_a','unit_review','K3-1-u3-C19',4,'essay','teacher','「양말 한 짝」에서 재미를 느낀 부분과 그 까닭을 친구들 앞에서 발표하는 말로 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K3-1-u3-C19","difficulty":4,"kind":"essay","stem":"「양말 한 짝」에서 재미를 느낀 부분과 그 까닭을 친구들 앞에서 발표하는 말로 쓰세요.","answer_guide":{"answer":"예: 저는 「혹시 너 혼자 / 여행 갔니?」 부분이 재미있었어요. 왜냐하면 사라진 양말이 혼자 여행을 떠났다는 생각이 엉뚱해서 웃음이 났기 때문이에요.","scoring_points":["재미를 느낀 부분을 썼는가","까닭을 썼는가","발표하는 말로 썼는가"]},"explanation":["부분","까닭","발표"],"asset":{"type":"passage","lines":["빨래 바구니에서","양말 한 짝이 사라졌다","소파 밑에도 없고","침대 밑에도 없다","혹시 너 혼자","여행 갔니?"],"title":"양말 한 짝"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u3_review_a#25','kor',3,1,'u3','','g3_1_kor_u3_review_a','unit_review','K3-1-u3-C28',4,'essay','teacher','내가 좋아하는 것을 주제로 「나」 설명서를 쓰고, 스스로 점검한 내용을 한 가지 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K3-1-u3-C28","difficulty":4,"kind":"essay","stem":"내가 좋아하는 것을 주제로 「나」 설명서를 쓰고, 스스로 점검한 내용을 한 가지 쓰세요.","answer_guide":{"answer":"예: 나는 자전거 타기를 좋아합니다. 주말마다 공원에서 자전거를 탑니다. 언덕길도 쉬지 않고 오를 수 있습니다. 바람을 가르며 달릴 때 가장 신납니다. 점검 — 뒷받침 문장이 모두 자전거 타기 이야기라서 중심 문장과 어울린다.","scoring_points":["중심 문장을 썼는가","어울리는 뒷받침 문장을 썼는가","점검한 내용을 썼는가"]},"explanation":["중심","뒷받침","점검"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u3_review_b#1','kor',3,1,'u3','','g3_1_kor_u3_review_b','unit_review','K3-1-u3-C4',1,'mc','auto','「비 오는 날의 소리」의 중심 문장은 무엇일까요?',ARRAY['K3-1-u3-X06','K3-1-u3-X04']::text[],false,'{"seq":1,"concept":"K3-1-u3-C4","difficulty":1,"kind":"mc","stem":"「비 오는 날의 소리」의 중심 문장은 무엇일까요?","options":[{"t":"비 오는 날에는 여러 가지 소리가 들립니다.","correct":true},{"t":"창문에 빗방울이 톡톡 부딪칩니다.","mis":"K3-1-u3-X06"},{"t":"자동차가 지나가면 고인 물이 촤악 튑니다.","mis":"K3-1-u3-X04"},{"t":"지붕 위에서는 빗물이 똑똑 떨어집니다.","mis":"K3-1-u3-X06"}],"explanation":["여러 가지 소리","묶는 문장","중심"],"asset":{"type":"passage","lines":["비 오는 날에는 여러 가지 소리가 들립니다.","창문에 빗방울이 톡톡 부딪칩니다.","지붕 위에서는 빗물이 똑똑 떨어집니다.","자동차가 지나가면 고인 물이 촤악 튑니다."],"title":"비 오는 날의 소리"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u3_review_b#2','kor',3,1,'u3','','g3_1_kor_u3_review_b','unit_review','K3-1-u3-C15',1,'mc','auto','「빈 의자」를 읽고 마음이 뭉클했다면 무엇을 느낀 것일까요?',ARRAY['K3-1-u3-X14','K3-1-u3-X15','K3-1-u3-X20']::text[],false,'{"seq":2,"concept":"K3-1-u3-C15","difficulty":1,"kind":"mc","stem":"「빈 의자」를 읽고 마음이 뭉클했다면 무엇을 느낀 것일까요?","options":[{"t":"감동","correct":true},{"t":"재미만","mis":"K3-1-u3-X14"},{"t":"지루함","mis":"K3-1-u3-X15"},{"t":"화남","mis":"K3-1-u3-X20"}],"explanation":["뭉클","그리움","감동"],"asset":{"type":"passage","lines":["짝꿍이 전학 간 날","옆 의자가 텅 비었어요","지우개 빌려 달라고","쿡쿡 찌를 데가 없어요","비어 있는 의자만큼","보고 싶은 마음이 커져요"],"title":"빈 의자"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
