INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u3_review_b#5','kor',3,1,'u3','','g3_1_kor_u3_review_b','unit_review','K3-1-u3-C12',1,'mc','auto','뒷받침 문장이 하나도 없는 문단은 어떨까요?',ARRAY['K3-1-u3-X11','K3-1-u3-X09']::text[],false,'{"seq":5,"concept":"K3-1-u3-C12","difficulty":1,"kind":"mc","stem":"뒷받침 문장이 하나도 없는 문단은 어떨까요?","options":[{"t":"생각을 자세히 알 수 없어요.","correct":true},{"t":"그것만으로 짜임새가 좋아요.","mis":"K3-1-u3-X11"},{"t":"가장 좋은 문단이에요.","mis":"K3-1-u3-X11"},{"t":"관계없는 문장을 넣으면 돼요.","mis":"K3-1-u3-X09"}],"explanation":["중심만","자세히 몰라요","뒷받침 필요"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
