INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u3_review_b#7','kor',3,1,'u3','','g3_1_kor_u3_review_b','unit_review','K3-1-u3-C17',1,'mc','auto','작품과 비슷한 경험을 떠올리면 어떤 점이 좋을까요?',ARRAY['K3-1-u3-X15','K3-1-u3-X16','K3-1-u3-X26']::text[],false,'{"seq":7,"concept":"K3-1-u3-C17","difficulty":1,"kind":"mc","stem":"작품과 비슷한 경험을 떠올리면 어떤 점이 좋을까요?","options":[{"t":"작품이 더 가깝게 느껴져요.","correct":true},{"t":"작품을 읽지 않아도 돼요.","mis":"K3-1-u3-X15"},{"t":"내 이야기만 길게 할 수 있어요.","mis":"K3-1-u3-X16"},{"t":"친구 경험을 베낄 수 있어요.","mis":"K3-1-u3-X26"}],"explanation":["닮은 경험","가깝게","느껴져요"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
