INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u3_review_b#9','kor',3,1,'u3','','g3_1_kor_u3_review_b','unit_review','K3-1-u3-C10',2,'mc','auto','「여름 방학」에서 다른 생각이 섞인 문장을 모두 고른 것은 무엇일까요?',ARRAY['K3-1-u3-X09','K3-1-u3-X03']::text[],false,'{"seq":9,"concept":"K3-1-u3-C10","difficulty":2,"kind":"mc","stem":"「여름 방학」에서 다른 생각이 섞인 문장을 모두 고른 것은 무엇일까요?","options":[{"t":"셋째 · 넷째 문장","correct":true},{"t":"첫째 · 둘째 문장","mis":"K3-1-u3-X09"},{"t":"둘째 문장만","mis":"K3-1-u3-X09"},{"t":"섞인 문장이 없어요","mis":"K3-1-u3-X03"}],"explanation":["바닷가 이야기","교실 · 짝","섞인 문장"],"asset":{"type":"passage","lines":["여름 방학에 가족과 바닷가에 다녀왔습니다.","모래성을 쌓고 조개껍데기를 주웠습니다.","우리 반 교실은 3층에 있습니다.","내 짝은 줄넘기를 잘합니다."],"title":"여름 방학"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u3_review_b#10','kor',3,1,'u3','','g3_1_kor_u3_review_b','unit_review','K3-1-u3-C12',2,'mc','auto','「우리 반 교실은 깨끗합니다.」에 이어 쓸 뒷받침 문장 두 개로 알맞은 것은 무엇일까요?',ARRAY['K3-1-u3-X08','K3-1-u3-X09','K3-1-u3-X11']::text[],false,'{"seq":10,"concept":"K3-1-u3-C12","difficulty":2,"kind":"mc","stem":"「우리 반 교실은 깨끗합니다.」에 이어 쓸 뒷받침 문장 두 개로 알맞은 것은 무엇일까요?","options":[{"t":"바닥에 쓰레기가 없습니다. 책상 위가 늘 가지런합니다.","correct":true},{"t":"우리 반 교실은 깨끗합니다. 정말 깨끗합니다.","mis":"K3-1-u3-X08"},{"t":"급식이 맛있습니다. 운동장이 넓습니다.","mis":"K3-1-u3-X09"},{"t":"없어도 돼요 — 중심 문장이 있으니까요.","mis":"K3-1-u3-X11"}],"explanation":["깨끗한 까닭","두 가지","뒷받침"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u3_review_b#11','kor',3,1,'u3','','g3_1_kor_u3_review_b','unit_review','K3-1-u3-C18',2,'mc','auto','「양말 한 짝」을 낭송할 때 어울리는 방법은 무엇일까요?',ARRAY['K3-1-u3-X14','K3-1-u3-X17','K3-1-u3-X15']::text[],false,'{"seq":11,"concept":"K3-1-u3-C18","difficulty":2,"kind":"mc","stem":"「양말 한 짝」을 낭송할 때 어울리는 방법은 무엇일까요?","options":[{"t":"고개를 갸웃하며 궁금한 듯 장난스럽게 읽는다.","correct":true},{"t":"아주 슬프게 울먹이며 읽는다.","mis":"K3-1-u3-X14"},{"t":"가장 빠르게 숨도 안 쉬고 읽는다.","mis":"K3-1-u3-X17"},{"t":"표정 없이 글자만 읽는다.","mis":"K3-1-u3-X15"}],"explanation":["궁금함","장난스럽게","낭송"],"asset":{"type":"passage","lines":["빨래 바구니에서","양말 한 짝이 사라졌다","소파 밑에도 없고","침대 밑에도 없다","혹시 너 혼자","여행 갔니?"],"title":"양말 한 짝"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u3_review_b#12','kor',3,1,'u3','','g3_1_kor_u3_review_b','unit_review','K3-1-u3-C20',2,'mc','auto','친구가 나와 다른 장면에서 감동을 받았다고 할 때 알맞은 말은 무엇일까요?',ARRAY['K3-1-u3-X19','K3-1-u3-X26']::text[],false,'{"seq":12,"concept":"K3-1-u3-C20","difficulty":2,"kind":"mc","stem":"친구가 나와 다른 장면에서 감동을 받았다고 할 때 알맞은 말은 무엇일까요?","options":[{"t":"「그 장면에서 왜 그렇게 느꼈는지 궁금해.」","correct":true},{"t":"「그건 감동받을 장면이 아니야.」","mis":"K3-1-u3-X19"},{"t":"「내 느낌이 맞으니 바꿔.」","mis":"K3-1-u3-X19"},{"t":"「그럼 나도 너처럼 느낄게.」","mis":"K3-1-u3-X26"}],"explanation":["다른 느낌","까닭 묻기","존중"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u3_review_b#13','kor',3,1,'u3','','g3_1_kor_u3_review_b','unit_review','K3-1-u3-C23',2,'mc','auto','「풀 자국도 묻어 있었습니다」에서 「자국」의 뜻으로 알맞은 것은 무엇일까요?',ARRAY['K3-1-u3-X22']::text[],false,'{"seq":13,"concept":"K3-1-u3-C23","difficulty":2,"kind":"mc","stem":"「풀 자국도 묻어 있었습니다」에서 「자국」의 뜻으로 알맞은 것은 무엇일까요?","options":[{"t":"무엇이 묻거나 닿아서 남은 흔적","correct":true},{"t":"풀이 자라는 곳","mis":"K3-1-u3-X22"},{"t":"새로 산 풀","mis":"K3-1-u3-X22"},{"t":"종이를 접은 모양","mis":"K3-1-u3-X22"}],"explanation":["묻어 있었다","남은 흔적","자국"],"asset":{"type":"passage","lines":["지후는 생일날 동생 다은이에게 연필꽂이를 선물로 받았습니다.","종이 상자로 만든 연필꽂이는 삐뚤빼뚤했습니다.","여기저기 풀 자국도 묻어 있었습니다.","「에이, 이게 뭐야.」 지후는 연필꽂이를 책상 구석으로 밀어 두었습니다.","다음 날 아침, 지후는 다은이 방 앞에서 구겨진 종이 세 장을 보았습니다.","종이마다 「오빠 생일 선물 만들기」라고 적혀 있었습니다.","지후는 연필꽂이를 책상 한가운데로 옮기고 연필을 하나씩 꽂았습니다.","「다은아, 고마워. 오늘부터 이걸로 쓸게.」"],"title":"삐뚤빼뚤 연필꽂이"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u3_review_b#14','kor',3,1,'u3','','g3_1_kor_u3_review_b','unit_review','K3-1-u3-C25',2,'mc','auto','재미나 감동을 표현하는 방법에 대해 바르게 말한 것은 무엇일까요?',ARRAY['K3-1-u3-X24','K3-1-u3-X26']::text[],false,'{"seq":14,"concept":"K3-1-u3-C25","difficulty":2,"kind":"mc","stem":"재미나 감동을 표현하는 방법에 대해 바르게 말한 것은 무엇일까요?","options":[{"t":"몸 · 그림 · 글 등 여러 방법으로 표현할 수 있어요.","correct":true},{"t":"글로만 표현할 수 있어요.","mis":"K3-1-u3-X24"},{"t":"그림으로만 표현할 수 있어요.","mis":"K3-1-u3-X24"},{"t":"잘하는 친구 것을 따라 하면 돼요.","mis":"K3-1-u3-X26"}],"explanation":["몸","그림","글"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u3_review_b#15','kor',3,1,'u3','','g3_1_kor_u3_review_b','unit_review','K3-1-u3-C32',2,'mc','auto','「백화점」의 바른 발음은 무엇일까요?',ARRAY['K3-1-u3-X29','K3-1-u3-X30']::text[],false,'{"seq":15,"concept":"K3-1-u3-C32","difficulty":2,"kind":"mc","stem":"「백화점」의 바른 발음은 무엇일까요?","options":[{"t":"[배콰점]","correct":true},{"t":"[백화점]","mis":"K3-1-u3-X29"},{"t":"[배과점]","mis":"K3-1-u3-X30"},{"t":"[백까점]","mis":"K3-1-u3-X30"}],"explanation":["받침 ㄱ","+ ㅎ","[ㅋ]"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u3_review_b#16','kor',3,1,'u3','','g3_1_kor_u3_review_b','unit_review','K3-1-u3-C30',2,'mc','auto','친구에게 책을 추천하는 글을 짜임새 있게 쓰는 방법은 무엇일까요?',ARRAY['K3-1-u3-X08','K3-1-u3-X03','K3-1-u3-X32']::text[],false,'{"seq":16,"concept":"K3-1-u3-C30","difficulty":2,"kind":"mc","stem":"친구에게 책을 추천하는 글을 짜임새 있게 쓰는 방법은 무엇일까요?","options":[{"t":"「이 책을 추천합니다.」를 중심 문장으로 쓰고 추천하는 까닭을 뒷받침 문장으로 쓴다.","correct":true},{"t":"책 제목만 여러 번 쓴다.","mis":"K3-1-u3-X08"},{"t":"책과 관계없는 일을 섞어 쓴다.","mis":"K3-1-u3-X03"},{"t":"짜임새는 국어 시간에만 생각한다.","mis":"K3-1-u3-X32"}],"explanation":["추천","까닭","짜임새"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u3_review_b#17','kor',3,1,'u3','','g3_1_kor_u3_review_b','unit_review','K3-1-u3-C7',3,'mc','auto','「줄넘기를 합니다. 공 던지기를 합니다. 달리기를 합니다.」를 모두 묶어 주는 중심 문장으로 알맞은 것은 무엇일까요?',ARRAY['K3-1-u3-X06','K3-1-u3-X09']::text[],false,'{"seq":17,"concept":"K3-1-u3-C7","difficulty":3,"kind":"mc","stem":"「줄넘기를 합니다. 공 던지기를 합니다. 달리기를 합니다.」를 모두 묶어 주는 중심 문장으로 알맞은 것은 무엇일까요?","options":[{"t":"체육 시간에는 여러 가지 운동을 합니다.","correct":true},{"t":"줄넘기는 재미있습니다.","mis":"K3-1-u3-X06"},{"t":"나는 달리기를 가장 잘합니다.","mis":"K3-1-u3-X09"},{"t":"체육 시간에는 줄넘기를 합니다.","mis":"K3-1-u3-X06"}],"explanation":["세 가지 운동","모두 묶는","중심 문장"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u3_review_b#18','kor',3,1,'u3','','g3_1_kor_u3_review_b','unit_review','K3-1-u3-C12',3,'mc','auto','「도서관은 좋습니다.」 한 문장만 쓴 글을 고쳐 쓴 것으로 가장 알맞은 것은 무엇일까요?',ARRAY['K3-1-u3-X08','K3-1-u3-X09','K3-1-u3-X11']::text[],false,'{"seq":18,"concept":"K3-1-u3-C12","difficulty":3,"kind":"mc","stem":"「도서관은 좋습니다.」 한 문장만 쓴 글을 고쳐 쓴 것으로 가장 알맞은 것은 무엇일까요?","options":[{"t":"우리 학교 도서관은 좋습니다. 읽고 싶은 책이 많습니다. 조용히 읽을 자리도 넉넉합니다.","correct":true},{"t":"도서관은 좋습니다. 도서관은 좋습니다.","mis":"K3-1-u3-X08"},{"t":"도서관은 좋습니다. 나는 떡볶이를 좋아합니다.","mis":"K3-1-u3-X09"},{"t":"도서관은 좋습니다. 끝.","mis":"K3-1-u3-X11"}],"explanation":["중심","뒷받침 둘","고쳐 쓰기"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u3_review_b#19','kor',3,1,'u3','','g3_1_kor_u3_review_b','unit_review','K3-1-u3-C18',3,'mc','auto','「아빠 수염」과 「빈 의자」를 낭송할 때 알맞은 방법은 무엇일까요?',ARRAY['K3-1-u3-X17','K3-1-u3-X14']::text[],false,'{"seq":19,"concept":"K3-1-u3-C18","difficulty":3,"kind":"mc","stem":"「아빠 수염」과 「빈 의자」를 낭송할 때 알맞은 방법은 무엇일까요?","options":[{"t":"「아빠 수염」은 밝고 장난스럽게, 「빈 의자」는 느리고 차분하게 읽는다.","correct":true},{"t":"두 시 모두 같은 목소리로 빠르게 읽는다.","mis":"K3-1-u3-X17"},{"t":"「아빠 수염」은 슬프게, 「빈 의자」는 깔깔 웃으며 읽는다.","mis":"K3-1-u3-X14"},{"t":"두 시 모두 가장 크게 소리친다.","mis":"K3-1-u3-X17"}],"explanation":["재미 = 밝게","감동 = 차분하게","낭송"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u3_review_b#20','kor',3,1,'u3','','g3_1_kor_u3_review_b','unit_review','K3-1-u3-C24',3,'mc','auto','「도하의 감상 문단」에서 빼야 할 문장은 무엇일까요?',ARRAY['K3-1-u3-X23','K3-1-u3-X09']::text[],false,'{"seq":20,"concept":"K3-1-u3-C24","difficulty":3,"kind":"mc","stem":"「도하의 감상 문단」에서 빼야 할 문장은 무엇일까요?","options":[{"t":"우리 집에는 연필이 많다.","correct":true},{"t":"왜냐하면 동생의 정성을 알아준 것 같았기 때문이다.","mis":"K3-1-u3-X23"},{"t":"나는 지후가 연필을 하나씩 꽂는 장면이 좋았다.","mis":"K3-1-u3-X23"},{"t":"나도 동생이 준 선물을 소중히 여겨야겠다.","mis":"K3-1-u3-X09"}],"explanation":["느낀 부분","까닭","관계없는 문장"],"asset":{"type":"passage","lines":["나는 지후가 연필을 하나씩 꽂는 장면이 좋았다.","왜냐하면 동생의 정성을 알아준 것 같았기 때문이다.","우리 집에는 연필이 많다.","나도 동생이 준 선물을 소중히 여겨야겠다."],"title":"도하의 감상 문단"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u3_review_b#21','kor',3,1,'u3','','g3_1_kor_u3_review_b','unit_review','K3-1-u3-C29',3,'mc','auto','소개 자료를 만드는 차례로 알맞은 것은 무엇일까요?',ARRAY['K3-1-u3-X26','K3-1-u3-X28','K3-1-u3-X12']::text[],false,'{"seq":21,"concept":"K3-1-u3-C29","difficulty":3,"kind":"mc","stem":"소개 자료를 만드는 차례로 알맞은 것은 무엇일까요?","options":[{"t":"작품 고르기 → 느낀 재미 · 감동과 까닭 정리하기 → 표현 방법 정해 만들기","correct":true},{"t":"친구 자료 베끼기 → 내기","mis":"K3-1-u3-X26"},{"t":"제목만 쓰기 → 끝","mis":"K3-1-u3-X28"},{"t":"표현 방법 정하기 → 작품은 나중에 고르기","mis":"K3-1-u3-X12"}],"explanation":["고르기","정리하기","만들기"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u3_review_b#22','kor',3,1,'u3','','g3_1_kor_u3_review_b','unit_review','K3-1-u3-C1',3,'mc','auto','이 단원에서 배운 두 가지가 만나는 활동은 무엇일까요?',ARRAY['K3-1-u3-X17','K3-1-u3-X26','K3-1-u3-X02']::text[],false,'{"seq":22,"concept":"K3-1-u3-C1","difficulty":3,"kind":"mc","stem":"이 단원에서 배운 두 가지가 만나는 활동은 무엇일까요?","options":[{"t":"작품에서 느낀 재미 · 감동을 중심 문장과 뒷받침 문장으로 쓰기","correct":true},{"t":"작품을 빨리 읽고 덮기","mis":"K3-1-u3-X17"},{"t":"느낌 없이 줄거리만 베껴 쓰기","mis":"K3-1-u3-X26"},{"t":"문단 없이 낱말만 늘어놓기","mis":"K3-1-u3-X02"}],"explanation":["문단 쓰기","재미 · 감동","만나는 곳"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u3_review_b#23','kor',3,1,'u3','','g3_1_kor_u3_review_b','unit_review','K3-1-u3-C10',4,'essay','teacher','「여름 방학」에서 어울리지 않는 문장을 찾아 쓰고, 바닷가 이야기에 어울리는 문장으로 바꾸어 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K3-1-u3-C10","difficulty":4,"kind":"essay","stem":"「여름 방학」에서 어울리지 않는 문장을 찾아 쓰고, 바닷가 이야기에 어울리는 문장으로 바꾸어 쓰세요.","answer_guide":{"answer":"예: 「우리 반 교실은 3층에 있습니다.」와 「내 짝은 줄넘기를 잘합니다.」는 바닷가 이야기와 관계없다. 「파도가 밀려와 발목을 간질였습니다.」, 「저녁에는 바닷가에서 노을을 보았습니다.」로 바꾼다.","scoring_points":["어울리지 않는 문장 두 개를 찾았는가","바꾼 문장이 바닷가 이야기인가","한 가지 생각으로 이어지는가"]},"explanation":["찾기","바꾸기","한 생각"],"asset":{"type":"passage","lines":["여름 방학에 가족과 바닷가에 다녀왔습니다.","모래성을 쌓고 조개껍데기를 주웠습니다.","우리 반 교실은 3층에 있습니다.","내 짝은 줄넘기를 잘합니다."],"title":"여름 방학"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u3_review_b#24','kor',3,1,'u3','','g3_1_kor_u3_review_b','unit_review','K3-1-u3-C24',4,'essay','teacher','「빈 의자」에서 느낀 감동을 「왜냐하면」을 넣어 한 문단으로 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K3-1-u3-C24","difficulty":4,"kind":"essay","stem":"「빈 의자」에서 느낀 감동을 「왜냐하면」을 넣어 한 문단으로 쓰세요.","answer_guide":{"answer":"예: 나는 「비어 있는 의자만큼 / 보고 싶은 마음이 커져요」에서 감동을 느꼈다. 왜냐하면 빈자리가 클수록 친구를 그리워하는 마음도 크다는 것이 잘 느껴졌기 때문이다.","scoring_points":["느낀 부분을 중심 문장으로 썼는가","「왜냐하면」으로 까닭을 썼는가","한 문단으로 이어지는가"]},"explanation":["느낀 부분","왜냐하면","한 문단"],"asset":{"type":"passage","lines":["짝꿍이 전학 간 날","옆 의자가 텅 비었어요","지우개 빌려 달라고","쿡쿡 찌를 데가 없어요","비어 있는 의자만큼","보고 싶은 마음이 커져요"],"title":"빈 의자"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u3_review_b#25','kor',3,1,'u3','','g3_1_kor_u3_review_b','unit_review','K3-1-u3-C29',4,'essay','teacher','읽은 작품 하나를 골라 소개 자료에 들어갈 내용을 세 가지로 나누어 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K3-1-u3-C29","difficulty":4,"kind":"essay","stem":"읽은 작품 하나를 골라 소개 자료에 들어갈 내용을 세 가지로 나누어 쓰세요.","answer_guide":{"answer":"예: 작품 제목 — 삐뚤빼뚤 연필꽂이. 느낀 감동 — 지후가 연필꽂이를 한가운데로 옮기는 장면이 따뜻했다. 까닭 — 서툰 선물에 담긴 동생의 마음을 알아주었기 때문이다.","scoring_points":["작품 제목을 썼는가","느낀 재미나 감동을 썼는가","그렇게 느낀 까닭을 썼는가"]},"explanation":["제목","느낌","까닭"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u3_review_c#1','kor',3,1,'u3','','g3_1_kor_u3_review_c','unit_review','K3-1-u3-C5',1,'mc','auto','「창문에 빗방울이 톡톡 부딪칩니다.」는 「비 오는 날의 소리」에서 어떤 문장일까요?',ARRAY['K3-1-u3-X06','K3-1-u3-X09','K3-1-u3-X02']::text[],false,'{"seq":1,"concept":"K3-1-u3-C5","difficulty":1,"kind":"mc","stem":"「창문에 빗방울이 톡톡 부딪칩니다.」는 「비 오는 날의 소리」에서 어떤 문장일까요?","options":[{"t":"뒷받침 문장","correct":true},{"t":"중심 문장","mis":"K3-1-u3-X06"},{"t":"관계없는 문장","mis":"K3-1-u3-X09"},{"t":"제목","mis":"K3-1-u3-X02"}],"explanation":["빗소리의","한 가지 예","뒷받침"],"asset":{"type":"passage","lines":["비 오는 날에는 여러 가지 소리가 들립니다.","창문에 빗방울이 톡톡 부딪칩니다.","지붕 위에서는 빗물이 똑똑 떨어집니다.","자동차가 지나가면 고인 물이 촤악 튑니다."],"title":"비 오는 날의 소리"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u3_review_c#2','kor',3,1,'u3','','g3_1_kor_u3_review_c','unit_review','K3-1-u3-C18',1,'mc','auto','시를 마음을 살려 소리 내어 읽는 것을 무엇이라고 할까요?',ARRAY['K3-1-u3-X26','K3-1-u3-X17','K3-1-u3-X15']::text[],false,'{"seq":2,"concept":"K3-1-u3-C18","difficulty":1,"kind":"mc","stem":"시를 마음을 살려 소리 내어 읽는 것을 무엇이라고 할까요?","options":[{"t":"낭송","correct":true},{"t":"베껴 쓰기","mis":"K3-1-u3-X26"},{"t":"빨리 읽기 겨루기","mis":"K3-1-u3-X17"},{"t":"눈으로만 읽기","mis":"K3-1-u3-X15"}],"explanation":["마음 살려","소리 내어","낭송"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
