INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u3_review_c#4','kor',3,1,'u3','','g3_1_kor_u3_review_c','unit_review','K3-1-u3-C32',1,'mc','auto','「잡히다」의 바른 발음은 무엇일까요?',ARRAY['K3-1-u3-X29','K3-1-u3-X30']::text[],false,'{"seq":4,"concept":"K3-1-u3-C32","difficulty":1,"kind":"mc","stem":"「잡히다」의 바른 발음은 무엇일까요?","options":[{"t":"[자피다]","correct":true},{"t":"[잡히다]","mis":"K3-1-u3-X29"},{"t":"[자비다]","mis":"K3-1-u3-X30"},{"t":"[잡비다]","mis":"K3-1-u3-X30"}],"explanation":["받침 ㅂ","+ ㅎ","[ㅍ]"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u3_review_c#5','kor',3,1,'u3','','g3_1_kor_u3_review_c','unit_review','K3-1-u3-C11',1,'mc','auto','문단을 쓰기 전에 계획할 때 먼저 할 일은 무엇일까요?',ARRAY['K3-1-u3-X12','K3-1-u3-X26','K3-1-u3-X13']::text[],false,'{"seq":5,"concept":"K3-1-u3-C11","difficulty":1,"kind":"mc","stem":"문단을 쓰기 전에 계획할 때 먼저 할 일은 무엇일까요?","options":[{"t":"무엇에 대해 쓸지 중심 생각을 정한다.","correct":true},{"t":"쓰고 싶은 대로 바로 쓴다.","mis":"K3-1-u3-X12"},{"t":"친구 글을 먼저 베낀다.","mis":"K3-1-u3-X26"},{"t":"글자 수부터 센다.","mis":"K3-1-u3-X13"}],"explanation":["먼저","중심 생각","정하기"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u3_review_c#6','kor',3,1,'u3','','g3_1_kor_u3_review_c','unit_review','K3-1-u3-C8',1,'mc','auto','중심 문장이 올 수 있는 자리를 모두 말한 것은 무엇일까요?',ARRAY['K3-1-u3-X05','K3-1-u3-X04']::text[],false,'{"seq":6,"concept":"K3-1-u3-C8","difficulty":1,"kind":"mc","stem":"중심 문장이 올 수 있는 자리를 모두 말한 것은 무엇일까요?","options":[{"t":"앞 · 가운데 · 끝","correct":true},{"t":"앞에만","mis":"K3-1-u3-X05"},{"t":"끝에만","mis":"K3-1-u3-X05"},{"t":"가장 긴 문장 자리에만","mis":"K3-1-u3-X04"}],"explanation":["앞","가운데","끝"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u3_review_c#7','kor',3,1,'u3','','g3_1_kor_u3_review_c','unit_review','K3-1-u3-C20',1,'mc','auto','같은 작품을 읽고 친구와 느낌이 다를 수 있을까요?',ARRAY['K3-1-u3-X19']::text[],false,'{"seq":7,"concept":"K3-1-u3-C20","difficulty":1,"kind":"mc","stem":"같은 작품을 읽고 친구와 느낌이 다를 수 있을까요?","options":[{"t":"네, 사람마다 다르게 느낄 수 있어요.","correct":true},{"t":"아니요, 느낌은 하나만 맞아요.","mis":"K3-1-u3-X19"},{"t":"아니요, 다르면 다시 읽어야 해요.","mis":"K3-1-u3-X19"},{"t":"아니요, 선생님과 같아야 해요.","mis":"K3-1-u3-X19"}],"explanation":["사람마다","다르게","느껴요"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u3_review_c#8','kor',3,1,'u3','','g3_1_kor_u3_review_c','unit_review','K3-1-u3-C29',1,'mc','auto','작품 소개 자료에 「그렇게 느낀 까닭」을 쓰는 까닭은 무엇일까요?',ARRAY['K3-1-u3-X28','K3-1-u3-X26']::text[],false,'{"seq":8,"concept":"K3-1-u3-C29","difficulty":1,"kind":"mc","stem":"작품 소개 자료에 「그렇게 느낀 까닭」을 쓰는 까닭은 무엇일까요?","options":[{"t":"보는 사람이 내 느낌을 더 잘 이해할 수 있어서","correct":true},{"t":"없어도 되지만 칸을 채우려고","mis":"K3-1-u3-X28"},{"t":"친구 까닭을 베끼려고","mis":"K3-1-u3-X26"},{"t":"제목을 대신하려고","mis":"K3-1-u3-X28"}],"explanation":["까닭이 있으면","느낌이","잘 전해져요"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u3_review_c#9','kor',3,1,'u3','','g3_1_kor_u3_review_c','unit_review','K3-1-u3-C5',2,'mc','auto','「비 오는 날의 소리」의 뒷받침 문장들이 공통으로 하는 일은 무엇일까요?',ARRAY['K3-1-u3-X08','K3-1-u3-X09','K3-1-u3-X06']::text[],false,'{"seq":9,"concept":"K3-1-u3-C5","difficulty":2,"kind":"mc","stem":"「비 오는 날의 소리」의 뒷받침 문장들이 공통으로 하는 일은 무엇일까요?","options":[{"t":"비 오는 날 들리는 소리를 예로 들어요.","correct":true},{"t":"중심 문장을 똑같이 되풀이해요.","mis":"K3-1-u3-X08"},{"t":"비와 관계없는 이야기를 해요.","mis":"K3-1-u3-X09"},{"t":"글 전체를 대표해요.","mis":"K3-1-u3-X06"}],"explanation":["톡톡 · 똑똑 · 촤악","소리의 예","뒷받침"],"asset":{"type":"passage","lines":["비 오는 날에는 여러 가지 소리가 들립니다.","창문에 빗방울이 톡톡 부딪칩니다.","지붕 위에서는 빗물이 똑똑 떨어집니다.","자동차가 지나가면 고인 물이 촤악 튑니다."],"title":"비 오는 날의 소리"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u3_review_c#10','kor',3,1,'u3','','g3_1_kor_u3_review_c','unit_review','K3-1-u3-C13',2,'mc','auto','점검하다가 관계없는 문장을 찾았을 때 알맞은 행동은 무엇일까요?',ARRAY['K3-1-u3-X13','K3-1-u3-X10','K3-1-u3-X06']::text[],false,'{"seq":10,"concept":"K3-1-u3-C13","difficulty":2,"kind":"mc","stem":"점검하다가 관계없는 문장을 찾았을 때 알맞은 행동은 무엇일까요?","options":[{"t":"빼거나 어울리는 문장으로 고쳐 쓴다.","correct":true},{"t":"점검은 끝났으니 그대로 둔다.","mis":"K3-1-u3-X13"},{"t":"다른 관계없는 문장으로 바꾼다.","mis":"K3-1-u3-X10"},{"t":"중심 문장을 지운다.","mis":"K3-1-u3-X06"}],"explanation":["찾으면","빼거나 고치기","점검"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u3_review_c#11','kor',3,1,'u3','','g3_1_kor_u3_review_c','unit_review','K3-1-u3-C16',2,'mc','auto','「양말 한 짝」을 읽고 떠올릴 장면으로 알맞은 것은 무엇일까요?',ARRAY['K3-1-u3-X20','K3-1-u3-X15']::text[],false,'{"seq":11,"concept":"K3-1-u3-C16","difficulty":2,"kind":"mc","stem":"「양말 한 짝」을 읽고 떠올릴 장면으로 알맞은 것은 무엇일까요?","options":[{"t":"아이가 이곳저곳 엎드려 양말을 찾는 모습","correct":true},{"t":"아이가 새 양말을 사러 가는 모습","mis":"K3-1-u3-X20"},{"t":"양말이 빨랫줄에 가지런히 널린 모습","mis":"K3-1-u3-X15"},{"t":"아이가 친구와 다투는 모습","mis":"K3-1-u3-X15"}],"explanation":["소파 밑","침대 밑","찾는 모습"],"asset":{"type":"passage","lines":["빨래 바구니에서","양말 한 짝이 사라졌다","소파 밑에도 없고","침대 밑에도 없다","혹시 너 혼자","여행 갔니?"],"title":"양말 한 짝"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u3_review_c#12','kor',3,1,'u3','','g3_1_kor_u3_review_c','unit_review','K3-1-u3-C15',2,'mc','auto','「삐뚤빼뚤 연필꽂이」에서 감동을 느낄 수 있는 까닭은 무엇일까요?',ARRAY['K3-1-u3-X14','K3-1-u3-X15']::text[],false,'{"seq":12,"concept":"K3-1-u3-C15","difficulty":2,"kind":"mc","stem":"「삐뚤빼뚤 연필꽂이」에서 감동을 느낄 수 있는 까닭은 무엇일까요?","options":[{"t":"서툴러도 마음을 다한 동생과 그 마음을 알아준 오빠가 따뜻해서","correct":true},{"t":"연필꽂이가 삐뚤빼뚤해서 웃겨서","mis":"K3-1-u3-X14"},{"t":"이야기에 웃긴 말이 많아서","mis":"K3-1-u3-X14"},{"t":"연필이 많이 나와서","mis":"K3-1-u3-X15"}],"explanation":["동생의 마음","오빠의 마음","감동"],"asset":{"type":"passage","lines":["지후는 생일날 동생 다은이에게 연필꽂이를 선물로 받았습니다.","종이 상자로 만든 연필꽂이는 삐뚤빼뚤했습니다.","여기저기 풀 자국도 묻어 있었습니다.","「에이, 이게 뭐야.」 지후는 연필꽂이를 책상 구석으로 밀어 두었습니다.","다음 날 아침, 지후는 다은이 방 앞에서 구겨진 종이 세 장을 보았습니다.","종이마다 「오빠 생일 선물 만들기」라고 적혀 있었습니다.","지후는 연필꽂이를 책상 한가운데로 옮기고 연필을 하나씩 꽂았습니다.","「다은아, 고마워. 오늘부터 이걸로 쓸게.」"],"title":"삐뚤빼뚤 연필꽂이"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u3_review_c#13','kor',3,1,'u3','','g3_1_kor_u3_review_c','unit_review','K3-1-u3-C24',2,'mc','auto','감상 문단의 짜임으로 알맞은 것은 무엇일까요?',ARRAY['K3-1-u3-X23']::text[],false,'{"seq":13,"concept":"K3-1-u3-C24","difficulty":2,"kind":"mc","stem":"감상 문단의 짜임으로 알맞은 것은 무엇일까요?","options":[{"t":"느낀 부분(중심 문장) → 느낀 까닭(뒷받침 문장)","correct":true},{"t":"느낀 까닭만 여러 줄","mis":"K3-1-u3-X23"},{"t":"까닭(중심 문장) → 느낀 부분(뒷받침 문장)","mis":"K3-1-u3-X23"},{"t":"작품 줄거리만 길게","mis":"K3-1-u3-X23"}],"explanation":["느낀 부분","까닭","짜임"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u3_review_c#14','kor',3,1,'u3','','g3_1_kor_u3_review_c','unit_review','K3-1-u3-C27',2,'mc','auto','나만의 방법으로 표현한다는 것은 무엇일까요?',ARRAY['K3-1-u3-X26','K3-1-u3-X18','K3-1-u3-X19']::text[],false,'{"seq":14,"concept":"K3-1-u3-C27","difficulty":2,"kind":"mc","stem":"나만의 방법으로 표현한다는 것은 무엇일까요?","options":[{"t":"내가 느낀 재미와 감동을 내 생각대로 나타내는 것","correct":true},{"t":"친구 작품을 그대로 베끼는 것","mis":"K3-1-u3-X26"},{"t":"느낌 없이 아무거나 그리는 것","mis":"K3-1-u3-X18"},{"t":"선생님 느낌을 그대로 옮기는 것","mis":"K3-1-u3-X19"}],"explanation":["내 느낌","내 생각대로","나만의 표현"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
