INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u3_review_c#16','kor',3,1,'u3','','g3_1_kor_u3_review_c','unit_review','K3-1-u3-C6',2,'mc','auto','두 문단으로 된 글에서 둘째 문단을 시작할 때 어떻게 쓸까요?',ARRAY['K3-1-u3-X07','K3-1-u3-X02']::text[],false,'{"seq":16,"concept":"K3-1-u3-C6","difficulty":2,"kind":"mc","stem":"두 문단으로 된 글에서 둘째 문단을 시작할 때 어떻게 쓸까요?","options":[{"t":"줄을 바꾸고 한 칸 들여 써요.","correct":true},{"t":"첫째 문단 끝에 바로 이어 써요.","mis":"K3-1-u3-X07"},{"t":"문장마다 줄을 바꿔요.","mis":"K3-1-u3-X02"},{"t":"들여 쓰지 않아도 돼요.","mis":"K3-1-u3-X07"}],"explanation":["새 문단","줄 바꿈","들여 쓰기"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u3_review_c#17','kor',3,1,'u3','','g3_1_kor_u3_review_c','unit_review','K3-1-u3-C3',3,'mc','auto','「여름 방학」을 짜임새 있게 고치는 방법으로 알맞은 것은 무엇일까요?',ARRAY['K3-1-u3-X03','K3-1-u3-X02','K3-1-u3-X06']::text[],false,'{"seq":17,"concept":"K3-1-u3-C3","difficulty":3,"kind":"mc","stem":"「여름 방학」을 짜임새 있게 고치는 방법으로 알맞은 것은 무엇일까요?","options":[{"t":"교실 · 짝 이야기는 빼고 바닷가 이야기를 더 써요.","correct":true},{"t":"그대로 한 문단으로 두어요.","mis":"K3-1-u3-X03"},{"t":"문장마다 줄을 바꾸어 네 문단으로 나눠요.","mis":"K3-1-u3-X02"},{"t":"바닷가 이야기는 빼고 교실 이야기만 남겨요.","mis":"K3-1-u3-X06"}],"explanation":["한 문단","한 생각","바닷가"],"asset":{"type":"passage","lines":["여름 방학에 가족과 바닷가에 다녀왔습니다.","모래성을 쌓고 조개껍데기를 주웠습니다.","우리 반 교실은 3층에 있습니다.","내 짝은 줄넘기를 잘합니다."],"title":"여름 방학"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u3_review_c#18','kor',3,1,'u3','','g3_1_kor_u3_review_c','unit_review','K3-1-u3-C13',3,'mc','auto','다 쓴 문단을 점검하는 차례로 알맞은 것은 무엇일까요?',ARRAY['K3-1-u3-X13']::text[],false,'{"seq":18,"concept":"K3-1-u3-C13","difficulty":3,"kind":"mc","stem":"다 쓴 문단을 점검하는 차례로 알맞은 것은 무엇일까요?","options":[{"t":"중심 문장 확인 → 뒷받침 문장이 어울리는지 확인 → 들여쓰기 확인","correct":true},{"t":"글자 수 세기 → 끝","mis":"K3-1-u3-X13"},{"t":"점검 없이 바로 내기","mis":"K3-1-u3-X13"},{"t":"친구 글과 길이 비교하기 → 끝","mis":"K3-1-u3-X13"}],"explanation":["중심","뒷받침","들여쓰기"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u3_review_c#19','kor',3,1,'u3','','g3_1_kor_u3_review_c','unit_review','K3-1-u3-C19',3,'mc','auto','감상 발표를 가장 잘한 것은 무엇일까요?',ARRAY['K3-1-u3-X18','K3-1-u3-X16','K3-1-u3-X26']::text[],false,'{"seq":19,"concept":"K3-1-u3-C19","difficulty":3,"kind":"mc","stem":"감상 발표를 가장 잘한 것은 무엇일까요?","options":[{"t":"「양말 한 짝」의 마지막 줄이 재미있었어요. 양말이 혼자 여행을 갔다는 생각이 엉뚱했거든요.","correct":true},{"t":"「양말 한 짝」이 재미있었어요. 끝.","mis":"K3-1-u3-X18"},{"t":"「양말 한 짝」을 읽었어요. 어제 축구를 했어요.","mis":"K3-1-u3-X16"},{"t":"친구가 재미있다고 해서 나도 재미있었어요.","mis":"K3-1-u3-X26"}],"explanation":["느낀 부분","까닭","발표"],"asset":{"type":"passage","lines":["빨래 바구니에서","양말 한 짝이 사라졌다","소파 밑에도 없고","침대 밑에도 없다","혹시 너 혼자","여행 갔니?"],"title":"양말 한 짝"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u3_review_c#20','kor',3,1,'u3','','g3_1_kor_u3_review_c','unit_review','K3-1-u3-C25',3,'mc','auto','「양말 한 짝」의 재미를 친구들에게 보여 주기에 어울리는 표현 방법과 까닭은 무엇일까요?',ARRAY['K3-1-u3-X25','K3-1-u3-X24']::text[],false,'{"seq":20,"concept":"K3-1-u3-C25","difficulty":3,"kind":"mc","stem":"「양말 한 짝」의 재미를 친구들에게 보여 주기에 어울리는 표현 방법과 까닭은 무엇일까요?","options":[{"t":"네 칸 만화 — 양말을 찾아다니는 장면을 차례대로 그릴 수 있어서","correct":true},{"t":"편지 — 몸짓으로 연기할 수 있어서","mis":"K3-1-u3-X25"},{"t":"역할극 — 그림으로 그릴 수 있어서","mis":"K3-1-u3-X25"},{"t":"표현하지 않기 — 시는 읽기만 하는 것이라서","mis":"K3-1-u3-X24"}],"explanation":["장면","차례대로","만화"],"asset":{"type":"passage","lines":["빨래 바구니에서","양말 한 짝이 사라졌다","소파 밑에도 없고","침대 밑에도 없다","혹시 너 혼자","여행 갔니?"],"title":"양말 한 짝"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u3_review_c#21','kor',3,1,'u3','','g3_1_kor_u3_review_c','unit_review','K3-1-u3-C32',3,'mc','auto','「입학」과 같은 까닭으로 소리가 바뀌는 낱말은 무엇일까요?',ARRAY['K3-1-u3-X30','K3-1-u3-X29']::text[],false,'{"seq":21,"concept":"K3-1-u3-C32","difficulty":3,"kind":"mc","stem":"「입학」과 같은 까닭으로 소리가 바뀌는 낱말은 무엇일까요?","options":[{"t":"먹히다","correct":true},{"t":"놓다","mis":"K3-1-u3-X30"},{"t":"좋지","mis":"K3-1-u3-X30"},{"t":"바다","mis":"K3-1-u3-X29"}],"explanation":["받침 ㅂ · ㄱ","+ ㅎ","먹히다 [머키다]"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u3_review_c#22','kor',3,1,'u3','','g3_1_kor_u3_review_c','unit_review','K3-1-u3-C9',3,'mc','auto','뒷받침 문장이 중심 문장과 어울리는지 알아보는 방법으로 알맞은 것은 무엇일까요?',ARRAY['K3-1-u3-X04','K3-1-u3-X09','K3-1-u3-X08']::text[],false,'{"seq":22,"concept":"K3-1-u3-C9","difficulty":3,"kind":"mc","stem":"뒷받침 문장이 중심 문장과 어울리는지 알아보는 방법으로 알맞은 것은 무엇일까요?","options":[{"t":"중심 문장 뒤에 이어 읽어 같은 생각을 말하는지 살핀다.","correct":true},{"t":"문장 길이가 비슷한지 본다.","mis":"K3-1-u3-X04"},{"t":"재미있는 문장인지만 본다.","mis":"K3-1-u3-X09"},{"t":"중심 문장과 낱말이 똑같은지 본다.","mis":"K3-1-u3-X08"}],"explanation":["이어 읽기","같은 생각","어울림"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u3_review_c#23','kor',3,1,'u3','','g3_1_kor_u3_review_c','unit_review','K3-1-u3-C12',4,'essay','teacher','「우리 반에는 재주가 많은 친구들이 있습니다.」를 중심 문장으로 하여 뒷받침 문장 세 개를 갖춘 문단을 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K3-1-u3-C12","difficulty":4,"kind":"essay","stem":"「우리 반에는 재주가 많은 친구들이 있습니다.」를 중심 문장으로 하여 뒷받침 문장 세 개를 갖춘 문단을 쓰세요.","answer_guide":{"answer":"예: 우리 반에는 재주가 많은 친구들이 있습니다. 서아는 리코더를 아주 잘 붑니다. 유찬이는 곤충 이름을 척척 맞힙니다. 태오는 달리기가 반에서 가장 빠릅니다.","scoring_points":["중심 문장으로 시작했는가","뒷받침 문장 세 개를 썼는가","모두 친구의 재주 이야기인가"]},"explanation":["중심","뒷받침 셋","어울림"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u3_review_c#24','kor',3,1,'u3','','g3_1_kor_u3_review_c','unit_review','K3-1-u3-C25',4,'essay','teacher','「삐뚤빼뚤 연필꽂이」에서 느낀 감동을 지후가 되어 다은이에게 보내는 짧은 편지로 표현하세요.','{}'::text[],false,'{"seq":24,"concept":"K3-1-u3-C25","difficulty":4,"kind":"essay","stem":"「삐뚤빼뚤 연필꽂이」에서 느낀 감동을 지후가 되어 다은이에게 보내는 짧은 편지로 표현하세요.","answer_guide":{"answer":"예: 다은아, 연필꽂이 정말 고마워. 처음에는 삐뚤빼뚤해서 구석에 밀어 두었는데, 구겨진 종이를 보고 네가 여러 번 다시 만든 걸 알았어. 이제 매일 이 연필꽂이를 쓸게. — 오빠가","scoring_points":["다은이에게 쓰는 편지 꼴인가","고마운 마음이 드러나는가","이야기 속 일을 근거로 썼는가"]},"explanation":["받는 사람","마음","이야기 속 일"],"asset":{"type":"passage","lines":["지후는 생일날 동생 다은이에게 연필꽂이를 선물로 받았습니다.","종이 상자로 만든 연필꽂이는 삐뚤빼뚤했습니다.","여기저기 풀 자국도 묻어 있었습니다.","「에이, 이게 뭐야.」 지후는 연필꽂이를 책상 구석으로 밀어 두었습니다.","다음 날 아침, 지후는 다은이 방 앞에서 구겨진 종이 세 장을 보았습니다.","종이마다 「오빠 생일 선물 만들기」라고 적혀 있었습니다.","지후는 연필꽂이를 책상 한가운데로 옮기고 연필을 하나씩 꽂았습니다.","「다은아, 고마워. 오늘부터 이걸로 쓸게.」"],"title":"삐뚤빼뚤 연필꽂이"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u3_review_c#25','kor',3,1,'u3','','g3_1_kor_u3_review_c','unit_review','K3-1-u3-C31',4,'essay','teacher','「쌓고」와 「착하다」의 바른 발음을 쓰고, 소리가 바뀌는 까닭을 각각 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K3-1-u3-C31","difficulty":4,"kind":"essay","stem":"「쌓고」와 「착하다」의 바른 발음을 쓰고, 소리가 바뀌는 까닭을 각각 쓰세요.","answer_guide":{"answer":"예: 「쌓고」는 [싸코]로 읽는다. 받침 ㅎ 뒤에 ㄱ이 와서 [ㅋ]으로 소리 난다. 「착하다」는 [차카다]로 읽는다. 받침 ㄱ 뒤에 ㅎ이 와서 [ㅋ]으로 소리 난다.","scoring_points":["「쌓고」의 발음을 바르게 썼는가","「착하다」의 발음을 바르게 썼는가","두 낱말의 까닭을 각각 썼는가"]},"explanation":["[싸코]","[차카다]","ㅎ이 만나면"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u3_review_d#1','kor',3,1,'u3','','g3_1_kor_u3_review_d','unit_review','K3-1-u3-C6',1,'mc','auto','문단의 첫 문장을 쓸 때 어떻게 할까요?',ARRAY['K3-1-u3-X07','K3-1-u3-X02']::text[],false,'{"seq":1,"concept":"K3-1-u3-C6","difficulty":1,"kind":"mc","stem":"문단의 첫 문장을 쓸 때 어떻게 할까요?","options":[{"t":"한 칸 들여 써요.","correct":true},{"t":"첫 칸부터 붙여 써요.","mis":"K3-1-u3-X07"},{"t":"두 줄을 비우고 써요.","mis":"K3-1-u3-X07"},{"t":"문장마다 줄을 바꿔 써요.","mis":"K3-1-u3-X02"}],"explanation":["첫 문장","한 칸","들여 쓰기"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u3_review_d#2','kor',3,1,'u3','','g3_1_kor_u3_review_d','unit_review','K3-1-u3-C19',1,'mc','auto','느낀 점을 발표할 때 「좋았어요.」 뒤에 덧붙이면 좋은 말은 무엇일까요?',ARRAY['K3-1-u3-X18','K3-1-u3-X26']::text[],false,'{"seq":2,"concept":"K3-1-u3-C19","difficulty":1,"kind":"mc","stem":"느낀 점을 발표할 때 「좋았어요.」 뒤에 덧붙이면 좋은 말은 무엇일까요?","options":[{"t":"「왜냐하면 ~ 때문이에요.」","correct":true},{"t":"「끝.」","mis":"K3-1-u3-X18"},{"t":"「친구도 그렇대요.」","mis":"K3-1-u3-X26"},{"t":"「다른 건 몰라요.」","mis":"K3-1-u3-X18"}],"explanation":["느낌","까닭","덧붙이기"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u3_review_d#3','kor',3,1,'u3','','g3_1_kor_u3_review_d','unit_review','K3-1-u3-C21',1,'mc','auto','「삐뚤빼뚤 연필꽂이」에서 생일 선물을 받은 사람은 누구일까요?',ARRAY['K3-1-u3-X20']::text[],false,'{"seq":3,"concept":"K3-1-u3-C21","difficulty":1,"kind":"mc","stem":"「삐뚤빼뚤 연필꽂이」에서 생일 선물을 받은 사람은 누구일까요?","options":[{"t":"지후","correct":true},{"t":"다은이","mis":"K3-1-u3-X20"},{"t":"엄마","mis":"K3-1-u3-X20"},{"t":"지후의 짝","mis":"K3-1-u3-X20"}],"explanation":["생일날","선물","지후"],"asset":{"type":"passage","lines":["지후는 생일날 동생 다은이에게 연필꽂이를 선물로 받았습니다.","종이 상자로 만든 연필꽂이는 삐뚤빼뚤했습니다.","여기저기 풀 자국도 묻어 있었습니다.","「에이, 이게 뭐야.」 지후는 연필꽂이를 책상 구석으로 밀어 두었습니다.","다음 날 아침, 지후는 다은이 방 앞에서 구겨진 종이 세 장을 보았습니다.","종이마다 「오빠 생일 선물 만들기」라고 적혀 있었습니다.","지후는 연필꽂이를 책상 한가운데로 옮기고 연필을 하나씩 꽂았습니다.","「다은아, 고마워. 오늘부터 이걸로 쓸게.」"],"title":"삐뚤빼뚤 연필꽂이"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
