INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u3_review_d#14','kor',3,1,'u3','','g3_1_kor_u3_review_d','unit_review','K3-1-u3-C28',2,'mc','auto','「나」 설명서의 중심 문장으로 알맞은 것은 무엇일까요?',ARRAY['K3-1-u3-X27','K3-1-u3-X06']::text[],false,'{"seq":14,"concept":"K3-1-u3-C28","difficulty":2,"kind":"mc","stem":"「나」 설명서의 중심 문장으로 알맞은 것은 무엇일까요?","options":[{"t":"나는 종이접기를 잘합니다.","correct":true},{"t":"어제는 비가 왔습니다.","mis":"K3-1-u3-X27"},{"t":"내 짝은 키가 큽니다.","mis":"K3-1-u3-X27"},{"t":"색종이를 반으로 접습니다.","mis":"K3-1-u3-X06"}],"explanation":["나를","대표하는","중심 문장"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u3_review_d#15','kor',3,1,'u3','','g3_1_kor_u3_review_d','unit_review','K3-1-u3-C31',2,'mc','auto','「그렇지」를 바르게 읽은 것은 무엇일까요?',ARRAY['K3-1-u3-X29','K3-1-u3-X30']::text[],false,'{"seq":15,"concept":"K3-1-u3-C31","difficulty":2,"kind":"mc","stem":"「그렇지」를 바르게 읽은 것은 무엇일까요?","options":[{"t":"[그러치]","correct":true},{"t":"[그렇지]","mis":"K3-1-u3-X29"},{"t":"[그러지]","mis":"K3-1-u3-X30"},{"t":"[그럳찌]","mis":"K3-1-u3-X30"}],"explanation":["받침 ㅎ","+ ㅈ","[ㅊ]"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u3_review_d#16','kor',3,1,'u3','','g3_1_kor_u3_review_d','unit_review','K3-1-u3-C2',2,'mc','auto','짜임새가 부족한 문단은 무엇일까요?',ARRAY['K3-1-u3-X01']::text[],false,'{"seq":16,"concept":"K3-1-u3-C2","difficulty":2,"kind":"mc","stem":"짜임새가 부족한 문단은 무엇일까요?","options":[{"t":"나는 강아지를 좋아합니다. 내일은 수요일입니다. 연필이 부러졌습니다.","correct":true},{"t":"나는 강아지를 좋아합니다. 강아지는 꼬리를 흔들며 반겨 줍니다. 털이 보드라워 쓰다듬기 좋습니다.","mis":"K3-1-u3-X01"},{"t":"비 오는 날에는 여러 가지 소리가 들립니다. 빗방울이 톡톡 부딪칩니다. 빗물이 똑똑 떨어집니다.","mis":"K3-1-u3-X01"},{"t":"우리 동네 시장에는 먹거리가 많습니다. 붕어빵을 팝니다. 어묵도 팝니다.","mis":"K3-1-u3-X01"}],"explanation":["한 가지 생각?","따로 노는 문장","짜임새 부족"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u3_review_d#17','kor',3,1,'u3','','g3_1_kor_u3_review_d','unit_review','K3-1-u3-C5',3,'mc','auto','「우리 동네 시장」의 뒷받침 문장들은 중심 문장을 어떻게 도와줄까요?',ARRAY['K3-1-u3-X08','K3-1-u3-X09','K3-1-u3-X06']::text[],false,'{"seq":17,"concept":"K3-1-u3-C5","difficulty":3,"kind":"mc","stem":"「우리 동네 시장」의 뒷받침 문장들은 중심 문장을 어떻게 도와줄까요?","options":[{"t":"붕어빵 · 떡 · 어묵처럼 먹거리의 예를 들어 줘요.","correct":true},{"t":"중심 문장을 낱말만 바꾸어 되풀이해요.","mis":"K3-1-u3-X08"},{"t":"시장과 관계없는 이야기로 재미를 줘요.","mis":"K3-1-u3-X09"},{"t":"스스로 문단을 대표해요.","mis":"K3-1-u3-X06"}],"explanation":["먹거리","예","뒷받침"],"asset":{"type":"passage","lines":["우리 동네 시장에는 맛있는 먹거리가 많습니다.","시장 입구에서는 갓 구운 붕어빵을 팝니다.","떡집에는 알록달록한 떡이 줄지어 놓여 있습니다.","시장 끝 가게에서는 따끈한 어묵 국물 냄새가 납니다."],"title":"우리 동네 시장"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u3_review_d#18','kor',3,1,'u3','','g3_1_kor_u3_review_d','unit_review','K3-1-u3-C11',3,'mc','auto','계획을 세우고 쓴 문단의 좋은 점은 무엇일까요?',ARRAY['K3-1-u3-X12','K3-1-u3-X13','K3-1-u3-X11']::text[],false,'{"seq":18,"concept":"K3-1-u3-C11","difficulty":3,"kind":"mc","stem":"계획을 세우고 쓴 문단의 좋은 점은 무엇일까요?","options":[{"t":"처음부터 끝까지 한 가지 생각으로 이어져요.","correct":true},{"t":"쓰다가 생각이 바뀌어 재미있어요.","mis":"K3-1-u3-X12"},{"t":"계획하면 점검할 필요가 없어요.","mis":"K3-1-u3-X13"},{"t":"계획하면 뒷받침 문장이 필요 없어요.","mis":"K3-1-u3-X11"}],"explanation":["계획","한 가지 생각","이어짐"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u3_review_d#19','kor',3,1,'u3','','g3_1_kor_u3_review_d','unit_review','K3-1-u3-C20',3,'mc','auto','감상 나누기에서 가장 바람직한 모습은 무엇일까요?',ARRAY['K3-1-u3-X19','K3-1-u3-X18','K3-1-u3-X26']::text[],false,'{"seq":19,"concept":"K3-1-u3-C20","difficulty":3,"kind":"mc","stem":"감상 나누기에서 가장 바람직한 모습은 무엇일까요?","options":[{"t":"서로 다른 느낌과 까닭을 끝까지 듣고 새롭게 알게 된 점을 말한다.","correct":true},{"t":"내 느낌과 다른 친구를 고쳐 준다.","mis":"K3-1-u3-X19"},{"t":"까닭은 빼고 느낌만 빨리 말한다.","mis":"K3-1-u3-X18"},{"t":"가장 많은 친구가 고른 느낌을 따라 한다.","mis":"K3-1-u3-X26"}],"explanation":["끝까지 듣기","서로 다른","새롭게 알기"],"asset":{"type":"speech","turns":[{"who":"도하","text":"나는 지후가 연필꽂이를 구석에 밀어 둔 장면이 속상했어. 다은이가 보면 얼마나 서운할까 싶었거든."},{"who":"유찬","text":"나는 연필을 하나씩 꽂는 마지막 장면이 기억에 남아. 오빠 마음이 바뀐 게 따뜻했어."},{"who":"서아","text":"같은 이야기인데 마음에 남은 장면이 다르구나. 둘 다 까닭을 들으니 이야기가 더 잘 보여."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u3_review_d#20','kor',3,1,'u3','','g3_1_kor_u3_review_d','unit_review','K3-1-u3-C23',3,'mc','auto','「삐뚤빼뚤」의 뜻을 짐작할 때 도움이 되는 앞뒤 내용은 무엇일까요?',ARRAY['K3-1-u3-X22']::text[],false,'{"seq":20,"concept":"K3-1-u3-C23","difficulty":3,"kind":"mc","stem":"「삐뚤빼뚤」의 뜻을 짐작할 때 도움이 되는 앞뒤 내용은 무엇일까요?","options":[{"t":"「종이 상자로 만든」, 「풀 자국도 묻어」처럼 서툴게 만든 모습","correct":true},{"t":"지후의 생일이라는 것","mis":"K3-1-u3-X22"},{"t":"연필이 여러 자루라는 것","mis":"K3-1-u3-X22"},{"t":"도움이 되는 내용은 없다","mis":"K3-1-u3-X22"}],"explanation":["앞뒤 내용","서툰 모습","짐작"],"asset":{"type":"passage","lines":["지후는 생일날 동생 다은이에게 연필꽂이를 선물로 받았습니다.","종이 상자로 만든 연필꽂이는 삐뚤빼뚤했습니다.","여기저기 풀 자국도 묻어 있었습니다.","「에이, 이게 뭐야.」 지후는 연필꽂이를 책상 구석으로 밀어 두었습니다.","다음 날 아침, 지후는 다은이 방 앞에서 구겨진 종이 세 장을 보았습니다.","종이마다 「오빠 생일 선물 만들기」라고 적혀 있었습니다.","지후는 연필꽂이를 책상 한가운데로 옮기고 연필을 하나씩 꽂았습니다.","「다은아, 고마워. 오늘부터 이걸로 쓸게.」"],"title":"삐뚤빼뚤 연필꽂이"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u3_review_d#21','kor',3,1,'u3','','g3_1_kor_u3_review_d','unit_review','K3-1-u3-C33',3,'mc','auto','「만날」과 「맨날」에 대한 설명으로 알맞은 것은 무엇일까요?',ARRAY['K3-1-u3-X31']::text[],false,'{"seq":21,"concept":"K3-1-u3-C33","difficulty":3,"kind":"mc","stem":"「만날」과 「맨날」에 대한 설명으로 알맞은 것은 무엇일까요?","options":[{"t":"뜻이 같고 둘 다 표준어예요.","correct":true},{"t":"「만날」만 표준어예요.","mis":"K3-1-u3-X31"},{"t":"「맨날」만 표준어예요.","mis":"K3-1-u3-X31"},{"t":"뜻이 서로 달라요.","mis":"K3-1-u3-X31"}],"explanation":["뜻이 같아요","둘 다","표준어"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u3_review_d#22','kor',3,1,'u3','','g3_1_kor_u3_review_d','unit_review','K3-1-u3-C27',3,'mc','auto','친구가 「내 만화가 다른 친구 것과 달라서 걱정이야.」라고 할 때 해 줄 말로 알맞은 것은 무엇일까요?',ARRAY['K3-1-u3-X26','K3-1-u3-X19','K3-1-u3-X24']::text[],false,'{"seq":22,"concept":"K3-1-u3-C27","difficulty":3,"kind":"mc","stem":"친구가 「내 만화가 다른 친구 것과 달라서 걱정이야.」라고 할 때 해 줄 말로 알맞은 것은 무엇일까요?","options":[{"t":"「네가 느낀 대로 그렸으니 달라도 괜찮아.」","correct":true},{"t":"「똑같이 다시 그려.」","mis":"K3-1-u3-X26"},{"t":"「만화는 정답이 하나야.」","mis":"K3-1-u3-X19"},{"t":"「차라리 그리지 마.」","mis":"K3-1-u3-X24"}],"explanation":["내 느낌","달라도","괜찮아"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u3_review_d#23','kor',3,1,'u3','','g3_1_kor_u3_review_d','unit_review','K3-1-u3-C8',4,'essay','teacher','「비 오는 날의 소리」의 중심 문장을 맨 끝으로 옮겨 문단을 다시 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K3-1-u3-C8","difficulty":4,"kind":"essay","stem":"「비 오는 날의 소리」의 중심 문장을 맨 끝으로 옮겨 문단을 다시 쓰세요.","answer_guide":{"answer":"예: 창문에 빗방울이 톡톡 부딪칩니다. 지붕 위에서는 빗물이 똑똑 떨어집니다. 자동차가 지나가면 고인 물이 촤악 튑니다. 이렇게 비 오는 날에는 여러 가지 소리가 들립니다.","scoring_points":["뒷받침 문장을 앞에 두었는가","중심 문장을 맨 끝에 두었는가","「이렇게」처럼 모아 정리하는 말을 넣었는가"]},"explanation":["뒷받침 먼저","중심은 끝","모아 정리"],"asset":{"type":"passage","lines":["비 오는 날에는 여러 가지 소리가 들립니다.","창문에 빗방울이 톡톡 부딪칩니다.","지붕 위에서는 빗물이 똑똑 떨어집니다.","자동차가 지나가면 고인 물이 촤악 튑니다."],"title":"비 오는 날의 소리"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u3_review_d#24','kor',3,1,'u3','','g3_1_kor_u3_review_d','unit_review','K3-1-u3-C17',4,'essay','teacher','「양말 한 짝」을 읽고 떠오른 장면과, 그와 비슷한 내 경험을 하나씩 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K3-1-u3-C17","difficulty":4,"kind":"essay","stem":"「양말 한 짝」을 읽고 떠오른 장면과, 그와 비슷한 내 경험을 하나씩 쓰세요.","answer_guide":{"answer":"예: 떠오른 장면 — 아이가 소파 밑과 침대 밑을 엎드려 들여다보며 양말을 찾는 모습. 비슷한 경험 — 아침에 실내화 한 짝이 없어져서 온 집 안을 찾아다닌 일.","scoring_points":["떠오른 장면을 썼는가","비슷한 경험을 썼는가","경험이 작품과 닮았는가"]},"explanation":["장면","경험","닮음"],"asset":{"type":"passage","lines":["빨래 바구니에서","양말 한 짝이 사라졌다","소파 밑에도 없고","침대 밑에도 없다","혹시 너 혼자","여행 갔니?"],"title":"양말 한 짝"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u3_review_d#25','kor',3,1,'u3','','g3_1_kor_u3_review_d','unit_review','K3-1-u3-C30',4,'essay','teacher','이 단원에서 배운 것을 생활 속 어느 때에 쓸 수 있는지 두 가지 상황을 들어 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K3-1-u3-C30","difficulty":4,"kind":"essay","stem":"이 단원에서 배운 것을 생활 속 어느 때에 쓸 수 있는지 두 가지 상황을 들어 쓰세요.","answer_guide":{"answer":"예: 학급 신문에 우리 동네를 소개할 때 중심 문장과 뒷받침 문장을 갖추어 쓰겠다. 친구에게 재미있게 읽은 책을 추천할 때 느낀 점과 까닭을 함께 쓰겠다.","scoring_points":["두 가지 상황을 썼는가","배운 것과 이어지는가","실천할 모습이 드러나는가"]},"explanation":["상황 하나","상황 둘","실천"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
